import com.google.gson.Gson;
import com.google.inject.Guice;
import com.google.inject.Injector;
import com.google.inject.util.Providers;
import haexporterplugin.HAExporterConfig;
import haexporterplugin.utils.HomeAssistUtils;
import haexporterplugin.utils.MessageBuilder;
import haexporterplugin.utils.RarityUtils;
import haexporterplugin.utils.ThievingUtils;
import haexporterplugin.utils.TickUtils;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.Player;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;
import org.junit.Before;
import org.junit.Test;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.*;

public class LootNotifierTest
{
	private static final int COIN_POUCH_ID = 1;
	private static final int ARROW_ID = 2;
	private static final int BOLT_ID = 3;

	private Client client;
	private HAExporterConfig config;
	private MessageBuilder messageBuilder;
	private LootNotifier lootNotifier;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		config = mock(HAExporterConfig.class);
		when(config.minLootValue()).thenReturn(25_000);
		when(config.lootItemAllowlist()).thenReturn("");
		when(config.lootItemDenylist()).thenReturn("");
		when(config.lootSourceDenylist()).thenReturn("");
		when(config.lootIncludePlayer()).thenReturn(true);
		when(config.lootIncludePickpocket()).thenReturn(true);
		when(config.lootIncludePkChest()).thenReturn(true);

		ItemComposition pouch = item(COIN_POUCH_ID, "Coin pouch");
		ItemComposition arrow = item(ARROW_ID, "Dragon arrow");
		ItemComposition bolt = item(BOLT_ID, "Dragon bolts");
		ItemManager itemManager = mock(ItemManager.class);
		when(itemManager.getItemComposition(anyInt())).thenAnswer(inv ->
		{
			int id = inv.getArgument(0);
			return id == COIN_POUCH_ID ? pouch : id == ARROW_ID ? arrow : bolt;
		});
		when(itemManager.getItemPrice(COIN_POUCH_ID)).thenReturn(50_000L);
		when(itemManager.getItemPrice(ARROW_ID)).thenReturn(15_000L);
		when(itemManager.getItemPrice(BOLT_ID)).thenReturn(15_000L);

		// Providers.of avoids Guice member-injecting the mocks' inherited @Inject fields
		Injector injector = Guice.createInjector(binder ->
		{
			binder.bind(Client.class).toProvider(Providers.of(client));
			binder.bind(ItemManager.class).toProvider(Providers.of(itemManager));
			binder.bind(HAExporterConfig.class).toProvider(Providers.of(config));
			binder.bind(TickUtils.class).toProvider(Providers.of(mock(TickUtils.class)));
			binder.bind(HomeAssistUtils.class).toProvider(Providers.of(mock(HomeAssistUtils.class)));
			binder.bind(RarityUtils.class).toProvider(Providers.of(mock(RarityUtils.class)));
			binder.bind(ThievingUtils.class).toProvider(Providers.of(mock(ThievingUtils.class)));
			binder.bind(Gson.class).toInstance(new Gson());
		});
		messageBuilder = injector.getInstance(MessageBuilder.class);
		lootNotifier = injector.getInstance(LootNotifier.class);
		lootNotifier.init();
	}

	@Test
	public void testPickpocketLootIsSentByDefault()
	{
		pickpocket();

		assertEquals(List.of("loot"), eventTypes());
	}

	@Test
	public void testPickpocketLootCanBeTurnedOff()
	{
		when(config.lootIncludePickpocket()).thenReturn(false);

		pickpocket();

		assertTrue(eventTypes().isEmpty());
	}

	@Test
	public void testPkChestUsesTotalValueByDefault()
	{
		pkChest();

		assertEquals(List.of("pkLoot"), eventTypes());
	}

	@Test
	public void testPkChestTotalValueCanBeTurnedOff()
	{
		when(config.lootIncludePkChest()).thenReturn(false);

		pkChest();

		assertTrue(eventTypes().isEmpty());
	}

	@Test
	public void testPkLootCanBeTurnedOff()
	{
		when(config.lootIncludePlayer()).thenReturn(false);
		Player victim = mock(Player.class);
		when(victim.getName()).thenReturn("Victim");

		lootNotifier.onPlayerLootReceived(new PlayerLootReceived(victim, List.of(new ItemStack(COIN_POUCH_ID, 1))));

		assertTrue(eventTypes().isEmpty());
		// Returns before the safe-area check even looks at the player
		verify(client, never()).getLocalPlayer();
	}

	private void pickpocket()
	{
		lootNotifier.onLootReceived(new LootReceived("Master Farmer", -1, LootRecordType.PICKPOCKET,
				List.of(new ItemStack(COIN_POUCH_ID, 1)), 1, null));
	}

	// Two items each below the 25k minimum, together above it
	private void pkChest()
	{
		lootNotifier.onLootReceived(new LootReceived("Loot Chest", -1, LootRecordType.EVENT,
				List.of(new ItemStack(ARROW_ID, 1), new ItemStack(BOLT_ID, 1)), 1, null));
	}

	private List<Object> eventTypes()
	{
		return messageBuilder.getRoot().getEvents().stream()
				.map(event -> ((Map<?, ?>) event).get("type"))
				.collect(Collectors.toList());
	}

	private static ItemComposition item(int id, String name)
	{
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getId()).thenReturn(id);
		when(composition.getName()).thenReturn(name);
		return composition;
	}
}

package haexporterplugin.notifiers;

import com.google.gson.Gson;
import com.google.inject.Guice;
import com.google.inject.Injector;
import com.google.inject.util.Providers;
import haexporterplugin.HAExporterConfig;
import haexporterplugin.utils.HomeAssistUtils;
import haexporterplugin.utils.MessageBuilder;
import haexporterplugin.utils.RarityUtils;
import haexporterplugin.utils.ThievingUtils;
import haexporterplugin.utils.TickUtils;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.events.GameStateChanged;
import org.junit.Before;
import org.junit.Test;

import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;

import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class LevelNotifierTest
{
	// Levels of the character the client currently reports
	private final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);

	private TickUtils tickUtils;
	private HAExporterConfig config;
	private MessageBuilder messageBuilder;
	private LevelNotifier levelNotifier;

	@Before
	public void setUp()
	{
		setAllLevels(50);

		Client client = mock(Client.class);
		when(client.getRealSkillLevel(any())).thenAnswer(inv -> levels.get(inv.<Skill>getArgument(0)));
		when(client.getSkillExperience(any())).thenAnswer(inv -> Experience.getXpForLevel(levels.get(inv.<Skill>getArgument(0))));
		when(client.getWorldType()).thenReturn(EnumSet.of(WorldType.MEMBERS));
		config = mock(HAExporterConfig.class);
		when(config.sendRate()).thenReturn(100);
		// Level-up filter defaults: send every level
		when(config.levelMinValue()).thenReturn(1);
		when(config.levelInterval()).thenReturn(1);
		when(config.levelIncludeVirtual()).thenReturn(true);
		when(config.levelIncludeCombat()).thenReturn(true);
		tickUtils = mock(TickUtils.class);
		// TickUtils counts ticks since the last send, which is usually well past the init delay
		when(tickUtils.getTickCount()).thenReturn(60);

		// Providers.of avoids Guice member-injecting the mocks' inherited @Inject fields
		Injector injector = Guice.createInjector(binder ->
		{
			binder.bind(Client.class).toProvider(Providers.of(client));
			binder.bind(HAExporterConfig.class).toProvider(Providers.of(config));
			binder.bind(TickUtils.class).toProvider(Providers.of(tickUtils));
			binder.bind(HomeAssistUtils.class).toProvider(Providers.of(mock(HomeAssistUtils.class)));
			binder.bind(RarityUtils.class).toProvider(Providers.of(mock(RarityUtils.class)));
			binder.bind(ThievingUtils.class).toProvider(Providers.of(mock(ThievingUtils.class)));
			binder.bind(Gson.class).toInstance(new Gson());
		});
		messageBuilder = injector.getInstance(MessageBuilder.class);
		levelNotifier = injector.getInstance(LevelNotifier.class);
	}

	@Test
	public void testNoLevelUpWhenHoppingBackFromSpecialWorld()
	{
		tick(5); // baseline on the normal world

		hop();
		setAllLevels(99); // e.g. a Leagues character
		tick(5);

		hop();
		setAllLevels(50); // back on the main account
		tick(5);

		assertNoLevelUp();
	}

	@Test
	public void testNoLevelUpAfterLoggingIntoAnotherAccount()
	{
		tick(5);

		levelNotifier.onGameStateChanged(gameState(GameState.LOGIN_SCREEN));
		setAllLevels(70);
		tick(5);

		assertNoLevelUp();
	}

	@Test
	public void testBaselineWaitsForTheNewWorldToLoad()
	{
		tick(5);

		hop();
		levelNotifier.onTick(); // first tick after the hop: the old character's stats can still be reported
		setAllLevels(99);
		tick(5);

		assertNoLevelUp();
	}

	@Test
	public void testRealLevelUpAfterHopIsStillReported()
	{
		tick(5);
		hop();
		tick(5);

		levels.put(Skill.ATTACK, 51);
		levelNotifier.onTick();

		verify(tickUtils).sendNow();
		assertEquals(1, messageBuilder.getRoot().getEvents().size());
	}

	@Test
	public void testIntervalFiltersEventsButStatsStillUpdate()
	{
		when(config.levelInterval()).thenReturn(5);
		tick(5);

		levels.put(Skill.MINING, 51);
		levelNotifier.onTick();
		assertNoLevelUp();
		assertEquals(Integer.valueOf(51), messageBuilder.getPlayer().getStats().getSkills().get("Mining").getLevel());

		levels.put(Skill.MINING, 55);
		levelNotifier.onTick();
		assertEquals(1, messageBuilder.getRoot().getEvents().size());
	}

	@Test
	public void testCombatLevelCanBeTurnedOff()
	{
		when(config.levelIncludeCombat()).thenReturn(false);
		tick(5);

		// Raising the combat skills raises the combat level too
		for (Skill skill : new Skill[]{Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.HITPOINTS, Skill.PRAYER})
		{
			levels.put(skill, 60);
		}
		levelNotifier.onTick();

		Map<?, ?> event = (Map<?, ?>) messageBuilder.getRoot().getEvents().get(0);
		String json = new Gson().toJson(event.get("data"));
		assertTrue(json.contains("Attack"));
		assertFalse(json.contains("Combat"));
	}

	private void hop()
	{
		levelNotifier.onGameStateChanged(gameState(GameState.HOPPING));
	}

	private void tick(int count)
	{
		for (int i = 0; i < count; i++)
		{
			levelNotifier.onTick();
		}
	}

	private void setAllLevels(int level)
	{
		for (Skill skill : Skill.values())
		{
			levels.put(skill, level);
		}
	}

	private void assertNoLevelUp()
	{
		verify(tickUtils, never()).sendNow();
		assertTrue(messageBuilder.getRoot().getEvents().isEmpty());
	}

	private static GameStateChanged gameState(GameState state)
	{
		GameStateChanged event = new GameStateChanged();
		event.setGameState(state);
		return event;
	}

	@Test
	public void testDefaultsSendEverything()
	{
		assertTrue(LevelNotifier.shouldSend("Attack", 2, 1, 1, true, true));
		assertTrue(LevelNotifier.shouldSend("Attack", 105, 1, 1, true, true));
		assertTrue(LevelNotifier.shouldSend("Combat", 50, 1, 1, true, true));
	}

	@Test
	public void testMinLevel()
	{
		assertFalse(LevelNotifier.shouldSend("Attack", 69, 70, 1, true, true));
		assertTrue(LevelNotifier.shouldSend("Attack", 70, 70, 1, true, true));
	}

	@Test
	public void testInterval()
	{
		assertFalse(LevelNotifier.shouldSend("Mining", 42, 1, 5, true, true));
		assertTrue(LevelNotifier.shouldSend("Mining", 45, 1, 5, true, true));
	}

	@Test
	public void testLevel99AlwaysSent()
	{
		assertTrue(LevelNotifier.shouldSend("Mining", 99, 1, 10, true, true));
	}

	@Test
	public void testVirtualLevels()
	{
		assertFalse(LevelNotifier.shouldSend("Mining", 100, 1, 1, false, true));
		assertTrue(LevelNotifier.shouldSend("Mining", 99, 1, 1, false, true));
		// combat level is never "virtual"
		assertTrue(LevelNotifier.shouldSend("Combat", 100, 1, 1, false, true));
	}

	@Test
	public void testCombatToggle()
	{
		assertFalse(LevelNotifier.shouldSend("Combat", 100, 1, 1, true, false));
		assertTrue(LevelNotifier.shouldSend("Attack", 60, 1, 1, true, false));
	}
}

package haexporterplugin.notifiers;

import com.google.gson.Gson;
import com.google.inject.Guice;
import com.google.inject.Injector;
import com.google.inject.util.Providers;
import haexporterplugin.HAExporterConfig;
import haexporterplugin.enums.CombatTaskTier;
import haexporterplugin.enums.DiaryTier;
import haexporterplugin.utils.HomeAssistUtils;
import haexporterplugin.utils.MessageBuilder;
import haexporterplugin.utils.RarityUtils;
import haexporterplugin.utils.ThievingUtils;
import haexporterplugin.utils.TickUtils;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TaskTierNotifierTest
{
	private static final String HARD_DIARY = "Well done! You have completed a hard task in the Varrock area. Your Achievement Diary has been updated.";
	private static final String ELITE_DIARY = "Well done! You have completed an elite task in the Varrock area. Your Achievement Diary has been updated.";
	private static final String MEDIUM_TASK = "Congratulations, you've completed a medium combat task: Hitting Them Where It Hurts.";
	private static final String MASTER_TASK = "Congratulations, you've completed a master combat task: Perfect Zulrah.";

	private HAExporterConfig config;
	private MessageBuilder messageBuilder;
	private AchievementDiaryNotifier diaryNotifier;
	private CombatTaskNotifier combatTaskNotifier;

	@Before
	public void setUp()
	{
		config = mock(HAExporterConfig.class);
		when(config.diaryMinTier()).thenReturn(DiaryTier.EASY);
		when(config.combatTaskMinTier()).thenReturn(CombatTaskTier.EASY);

		// Providers.of avoids Guice member-injecting the mocks' inherited @Inject fields
		Injector injector = Guice.createInjector(binder ->
		{
			binder.bind(Client.class).toProvider(Providers.of(mock(Client.class)));
			binder.bind(HAExporterConfig.class).toProvider(Providers.of(config));
			binder.bind(TickUtils.class).toProvider(Providers.of(mock(TickUtils.class)));
			binder.bind(HomeAssistUtils.class).toProvider(Providers.of(mock(HomeAssistUtils.class)));
			binder.bind(RarityUtils.class).toProvider(Providers.of(mock(RarityUtils.class)));
			binder.bind(ThievingUtils.class).toProvider(Providers.of(mock(ThievingUtils.class)));
			binder.bind(Gson.class).toInstance(new Gson());
		});
		messageBuilder = injector.getInstance(MessageBuilder.class);
		diaryNotifier = injector.getInstance(AchievementDiaryNotifier.class);
		combatTaskNotifier = injector.getInstance(CombatTaskNotifier.class);
	}

	@Test
	public void testDiaryDefaultSendsEveryTier()
	{
		diaryNotifier.onChatMessage(chat(HARD_DIARY));

		assertEquals(1, eventCount());
	}

	@Test
	public void testDiaryBelowMinimumTierIsSkipped()
	{
		when(config.diaryMinTier()).thenReturn(DiaryTier.ELITE);

		diaryNotifier.onChatMessage(chat(HARD_DIARY));
		assertEquals(0, eventCount());

		diaryNotifier.onChatMessage(chat(ELITE_DIARY));
		assertEquals(1, eventCount());
	}

	@Test
	public void testCombatTaskDefaultSendsEveryTier()
	{
		combatTaskNotifier.onChatMessage(chat(MEDIUM_TASK));

		assertEquals(1, eventCount());
	}

	@Test
	public void testCombatTaskBelowMinimumTierIsSkipped()
	{
		when(config.combatTaskMinTier()).thenReturn(CombatTaskTier.HARD);

		combatTaskNotifier.onChatMessage(chat(MEDIUM_TASK));
		assertEquals(0, eventCount());

		combatTaskNotifier.onChatMessage(chat(MASTER_TASK));
		assertEquals(1, eventCount());
	}

	private int eventCount()
	{
		return messageBuilder.getRoot().getEvents().size();
	}

	private static ChatMessage chat(String message)
	{
		ChatMessage event = new ChatMessage();
		event.setType(ChatMessageType.GAMEMESSAGE);
		event.setMessage(message);
		return event;
	}
}

package haexporterplugin.notifiers;

import com.google.gson.Gson;
import com.google.inject.Guice;
import com.google.inject.Injector;
import com.google.inject.util.Providers;
import haexporterplugin.HAExporterConfig;
import haexporterplugin.data.CollectionData;
import haexporterplugin.utils.HomeAssistUtils;
import haexporterplugin.utils.KillCountTracker;
import haexporterplugin.utils.MessageBuilder;
import haexporterplugin.utils.RarityUtils;
import haexporterplugin.utils.ThievingUtils;
import haexporterplugin.utils.TickUtils;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;

import java.util.List;
import java.util.Map;
import java.util.function.BooleanSupplier;

import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.*;

public class CollectionNotifierTest
{
	private static final int WHIP_ID = 4;
	private static final int CHAT_ONLY = 1;
	private static final int POPUP = 2;

	private int tick = 1000;
	private Client client;
	private HAExporterConfig config;
	private MessageBuilder messageBuilder;
	private KillCountTracker killCountTracker;
	private CollectionNotifier collectionNotifier;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		config = mock(HAExporterConfig.class);
		when(client.getTickCount()).thenAnswer(inv -> tick);
		when(client.getItemCount()).thenReturn(10);

		ItemComposition whip = item("Abyssal whip");
		ItemComposition unnamed = item("null");
		ItemManager itemManager = mock(ItemManager.class);
		when(itemManager.canonicalize(anyInt())).thenAnswer(inv -> inv.getArgument(0));
		when(itemManager.getItemComposition(anyInt())).thenAnswer(inv -> (int) inv.getArgument(0) == WHIP_ID ? whip : unnamed);
		when(itemManager.getItemPrice(WHIP_ID)).thenReturn(1_500_000L);

		// Runs deferred work right away, so the tests stay synchronous
		ClientThread clientThread = mock(ClientThread.class);
		doAnswer(inv -> { inv.<Runnable>getArgument(0).run(); return null; }).when(clientThread).invokeAtTickEnd(any());
		doAnswer(inv ->
		{
			BooleanSupplier task = inv.getArgument(0);
			while (!task.getAsBoolean())
			{
				// keep going until done
			}
			return null;
		}).when(clientThread).invokeLater(any(BooleanSupplier.class));

		// Providers.of avoids Guice member-injecting the mocks' inherited @Inject fields
		Injector injector = Guice.createInjector(binder ->
		{
			binder.bind(Client.class).toProvider(Providers.of(client));
			binder.bind(ItemManager.class).toProvider(Providers.of(itemManager));
			binder.bind(ClientThread.class).toProvider(Providers.of(clientThread));
			binder.bind(HAExporterConfig.class).toProvider(Providers.of(config));
			binder.bind(TickUtils.class).toProvider(Providers.of(mock(TickUtils.class)));
			binder.bind(HomeAssistUtils.class).toProvider(Providers.of(mock(HomeAssistUtils.class)));
			binder.bind(RarityUtils.class).toProvider(Providers.of(mock(RarityUtils.class)));
			binder.bind(ThievingUtils.class).toProvider(Providers.of(mock(ThievingUtils.class)));
			binder.bind(Gson.class).toInstance(new Gson());
		});
		messageBuilder = injector.getInstance(MessageBuilder.class);
		killCountTracker = injector.getInstance(KillCountTracker.class);
		collectionNotifier = injector.getInstance(CollectionNotifier.class);
	}

	@Test
	public void testChatOnlySettingUsesTheChatMessage()
	{
		setNotificationSetting(CHAT_ONLY);

		chat("New item added to your collection log: Abyssal whip");

		CollectionData item = onlyCollectionLogEvent();
		assertEquals("Abyssal whip", item.getItemName());
		assertEquals(WHIP_ID, item.getItemId());
		assertEquals(1_500_000L, item.getValue());
	}

	@Test
	public void testPopupSettingIgnoresTheChatMessage()
	{
		setNotificationSetting(POPUP);

		chat("New item added to your collection log: Abyssal whip");

		assertTrue(messageBuilder.getRoot().getEvents().isEmpty());
	}

	@Test
	public void testPopupIsUsed()
	{
		setNotificationSetting(POPUP);

		popup("Collection log", "New item:<br><col=ffffff>Abyssal whip</col>");

		assertEquals("Abyssal whip", onlyCollectionLogEvent().getItemName());
	}

	@Test
	public void testCollectionLogPopupWithoutNewItemIsIgnored()
	{
		setNotificationSetting(POPUP);

		popup("Collection log", "Something else entirely");

		assertTrue(messageBuilder.getRoot().getEvents().isEmpty());
	}

	@Test
	public void testKillCountSurvivesAQueuedPopup()
	{
		setNotificationSetting(POPUP);
		chat("Your Vorkath kill count is: 1,250.");
		tick++;
		killCountTracker.onDrop(tick);

		tick += 15; // shown after other popups
		popup("Collection log", "New item:<br>Abyssal whip");

		assertEquals(Integer.valueOf(1250), onlyCollectionLogEvent().getKillCount());
	}

	@Test
	public void testItemNameLookupIsBuiltAfterLogin()
	{
		GameStateChanged loggedIn = new GameStateChanged();
		loggedIn.setGameState(GameState.LOGGED_IN);
		collectionNotifier.onGameStateChanged(loggedIn);

		verify(client).getItemCount();
	}

	@Test
	public void testItemBelowMinimumValueIsSkipped()
	{
		setNotificationSetting(CHAT_ONLY);
		when(config.clogMinValue()).thenReturn(2_000_000);

		chat("New item added to your collection log: Abyssal whip");

		assertTrue(messageBuilder.getRoot().getEvents().isEmpty());
	}

	@Test
	public void testItemAboveMinimumValueIsSent()
	{
		setNotificationSetting(CHAT_ONLY);
		when(config.clogMinValue()).thenReturn(1_000_000);

		chat("New item added to your collection log: Abyssal whip");

		assertEquals("Abyssal whip", onlyCollectionLogEvent().getItemName());
	}

	@Test
	public void testItemWithoutPriceIgnoresMinimumValue()
	{
		setNotificationSetting(CHAT_ONLY);
		when(config.clogMinValue()).thenReturn(2_000_000);

		chat("New item added to your collection log: Pet snakeling");

		assertEquals("Pet snakeling", onlyCollectionLogEvent().getItemName());
	}

	@Test
	public void testParsePopupItemName()
	{
		assertEquals("Abyssal whip", CollectionNotifier.parsePopupItemName("Collection log", "New item:<br>Abyssal whip"));
		assertEquals("Abyssal whip", CollectionNotifier.parsePopupItemName("COLLECTION LOG", "New item: Abyssal whip "));
		assertNull(CollectionNotifier.parsePopupItemName("Combat Task", "New item:<br>Abyssal whip"));
		assertNull(CollectionNotifier.parsePopupItemName("Collection log", "New item:"));
		assertNull(CollectionNotifier.parsePopupItemName("Collection log", null));
		assertNull(CollectionNotifier.parsePopupItemName(null, "New item:<br>Abyssal whip"));
	}

	@Test
	public void testParseKillCount()
	{
		assertEquals(Integer.valueOf(1250), CollectionNotifier.parseKillCount("Your Vorkath kill count is: 1,250."));
		assertEquals(Integer.valueOf(42), CollectionNotifier.parseKillCount("Your completed Chambers of Xeric count is: 42."));
		assertNull(CollectionNotifier.parseKillCount("New item added to your collection log: Abyssal whip"));
	}

	private void setNotificationSetting(int value)
	{
		when(client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM)).thenReturn(value);
	}

	private void chat(String message)
	{
		ChatMessage event = new ChatMessage();
		event.setType(ChatMessageType.GAMEMESSAGE);
		event.setMessage(message);
		collectionNotifier.onChatMessage(event);
	}

	private void popup(String title, String body)
	{
		when(client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE)).thenReturn(title);
		when(client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN)).thenReturn(body);
		collectionNotifier.onScript(script(ScriptID.NOTIFICATION_START));
		collectionNotifier.onScript(script(ScriptID.NOTIFICATION_DELAY));
	}

	private static ScriptPreFired script(int scriptId)
	{
		return new ScriptPreFired(scriptId);
	}

	private CollectionData onlyCollectionLogEvent()
	{
		List<Object> events = messageBuilder.getRoot().getEvents();
		assertEquals(1, events.size());
		Map<?, ?> event = (Map<?, ?>) events.get(0);
		assertEquals("collectionLog", event.get("type"));
		return (CollectionData) event.get("data");
	}

	private static ItemComposition item(String name)
	{
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getName()).thenReturn(name);
		when(composition.getNote()).thenReturn(-1);
		when(composition.getPlaceholderTemplateId()).thenReturn(-1);
		return composition;
	}
}

