@RequiredArgsConstructor
public enum ExceptionalDeath {
    COX("Chambers of Xeric"),
    DIARY_RESURRECTION("Diary Resurrection"),
    FIGHT_CAVE("Fight Caves"),
    GAUNTLET("Gauntlet"),
