package haexporterplugin.utils;

import com.google.gson.Gson;
import haexporterplugin.data.*;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.UUID;

@Slf4j
@Singleton
public class MessageBuilder {

    @Inject
    private Gson gson;

    @Getter
    private Root root;

    public MessageBuilder() {
        this.root = new Root();
    }

    public Player getPlayer() {
        if (root.getPlayer() == null) {
            root.setPlayer(new Player());
        }
        return root.getPlayer();
    }

    public void setData(String category, Object data)
    {
        Player player = getPlayer();

        switch (category.toLowerCase()) {
            case "name":
                player.setName((String) data);
                break;
            case "accounthash":
                player.setAccountHash((String) data);
                break;
            case "accounttype":
                player.setAccountType((String) data);
                break;
            case "health":
                player.setHealth((HealthData) data);
                break;
            case "prayer":
                player.setPrayerPoints((PrayerData) data);
                break;
            case "spellbook":
                player.setSpellbook((SpellbookData) data);
                break;
            case "world":
                player.setWorld((String) data);
                break;
            case "worldtypes":
                player.setWorldTypes((String[]) data);
                break;
            case "location":
                player.setLocation((PlayerLocation) data);
                break;
            case "stats":
                player.setStats(data);
                break;
            case "inventory":
                player.setInventory(data);
                break;
            case "equipment":
                player.setEquipment(data);
                break;
            default:
                log.warn("Unknown category: {}", category);
                break;
        }
    }

    public void addEvent(String category, Object event)
    {
        Map<String, Object> eventMap = new LinkedHashMap<>();
        eventMap.put("type", category);
        eventMap.put("data", event);
        // Identical events can legitimately repeat (e.g. two diary tasks), so receivers dedupe on eventId
        eventMap.put("eventId", UUID.randomUUID().toString());
        eventMap.put("timestamp", System.currentTimeMillis());
        root.addEvent(eventMap);
    }

    public void resetEvents()
    {
        root.resetEvents();
    }

    public void setState(GameState state){
        root.setState(state);
    }

    public String build()
    {
        root.setTimestamp(System.currentTimeMillis());
        return gson.toJson(root);
    }

    public void resetData(){
        this.root = new Root();
    }

    public void setTickDelay(int tickDelay){
        root.setTickDelay(tickDelay);
    }
}

package haexporterplugin.utils;

import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import java.util.function.LongSupplier;

/**
 * Per-connection delivery state: when sending is paused, how long the next backoff lasts, and which
 * payloads with events are waiting to be resent. Kept in memory only and safe to use from any thread.
 */
public class ConnectionBackoff {
    static final long INITIAL_BACKOFF_MS = TimeUnit.SECONDS.toMillis(30);
    static final long MAX_BACKOFF_MS = TimeUnit.MINUTES.toMillis(10);
    static final int MAX_QUEUED_PAYLOADS = 50;
    static final long MAX_QUEUE_AGE_MS = TimeUnit.MINUTES.toMillis(10);
    // Lower bound for Retry-After pauses, so "Retry-After: 0" can't cause a tight retry loop
    static final long MIN_RETRY_AFTER_MS = TimeUnit.SECONDS.toMillis(1);

    public enum Outcome {
        SUCCESS,      // 2xx
        UNAUTHORIZED, // 401: token revoked, disable the connection
        GONE,         // 410: endpoint no longer accepts data, disable the connection
        RETRY_AFTER,  // 429 / 503: pause as long as Retry-After asks, back off when it is missing
        BACKOFF,      // other 5xx: exponential backoff
        REJECTED      // anything else: drop the payload, no backoff
    }

    private static final class QueuedPayload {
        private final String payload;
        private final long enqueuedAt;

        private QueuedPayload(String payload, long enqueuedAt) {
            this.payload = payload;
            this.enqueuedAt = enqueuedAt;
        }
    }

    private static final class State {
        // 0 while healthy, otherwise the end of the current (or most recent) pause
        private long pausedUntil;
        private long nextBackoff = INITIAL_BACKOFF_MS;
        private final Deque<QueuedPayload> queue = new ArrayDeque<>();
        // Queued payload that is currently being resent, null when none
        private QueuedPayload inFlight;
    }

    private final LongSupplier clock;
    private final Map<String, State> states = new HashMap<>();

    public ConnectionBackoff() {
        this(System::currentTimeMillis);
    }

    public ConnectionBackoff(LongSupplier clock) {
        this.clock = clock;
    }

    public static Outcome classify(int statusCode) {
        if (statusCode >= 200 && statusCode < 300) {
            return Outcome.SUCCESS;
        }
        if (statusCode == 401) {
            return Outcome.UNAUTHORIZED;
        }
        if (statusCode == 410) {
            return Outcome.GONE;
        }
        if (statusCode == 429 || statusCode == 503) {
            return Outcome.RETRY_AFTER;
        }
        if (statusCode >= 500 && statusCode < 600) {
            return Outcome.BACKOFF;
        }
        return Outcome.REJECTED;
    }

    /**
     * Parses a Retry-After header, either delta-seconds or an HTTP-date.
     *
     * @return the moment (epoch millis) to retry at, or null when missing or invalid
     */
    public static Long parseRetryAfter(String headerValue, long nowMillis) {
        if (headerValue == null || headerValue.trim().isEmpty()) {
            return null;
        }

        String value = headerValue.trim();
        if (value.chars().allMatch(c -> c >= '0' && c <= '9')) {
            try {
                return Math.addExact(nowMillis, Math.multiplyExact(Long.parseLong(value), 1000L));
            } catch (NumberFormatException | ArithmeticException e) {
                return null;
            }
        }

        try {
            return ZonedDateTime.parse(value, DateTimeFormatter.RFC_1123_DATE_TIME).toInstant().toEpochMilli();
        } catch (DateTimeParseException e) {
            return null;
        }
    }

    public synchronized boolean isPaused(String key) {
        return getPausedUntil(key) > 0;
    }

    /**
     * @return the end of the current pause in epoch millis, or 0 when not paused
     */
    public synchronized long getPausedUntil(String key) {
        State state = states.get(key);
        return state != null && state.pausedUntil > clock.getAsLong() ? state.pausedUntil : 0;
    }

    public synchronized int getQueuedCount(String key) {
        State state = states.get(key);
        if (state == null) {
            return 0;
        }
        prune(state);
        return state.queue.size();
    }

    public synchronized void recordSuccess(String key) {
        State state = states.get(key);
        if (state == null) {
            return;
        }
        state.pausedUntil = 0;
        state.nextBackoff = INITIAL_BACKOFF_MS;
        removeIfIdle(key, state);
    }

    /**
     * Pauses for the current backoff delay and doubles it for next time, up to {@link #MAX_BACKOFF_MS}.
     * A failure reported while already paused (a request that was in flight when the pause began) is ignored.
     *
     * @return true when this is the first failure since the last successful delivery
     */
    public synchronized boolean recordFailure(String key) {
        long now = clock.getAsLong();
        State state = states.computeIfAbsent(key, k -> new State());
        if (state.pausedUntil > now) {
            return false;
        }

        boolean firstFailure = state.pausedUntil == 0;
        state.pausedUntil = now + state.nextBackoff;
        state.nextBackoff = Math.min(state.nextBackoff * 2, MAX_BACKOFF_MS);
        return firstFailure;
    }

    /**
     * Pauses until the moment the server asked for, kept between {@link #MIN_RETRY_AFTER_MS} and
     * {@link #MAX_BACKOFF_MS} from now. Does not advance the exponential backoff.
     *
     * @return true when this is the first failure since the last successful delivery
     */
    public synchronized boolean recordRetryAfter(String key, long untilMillis) {
        long now = clock.getAsLong();
        State state = states.computeIfAbsent(key, k -> new State());
        boolean firstFailure = state.pausedUntil == 0;
        long until = Math.max(now + MIN_RETRY_AFTER_MS, Math.min(untilMillis, now + MAX_BACKOFF_MS));
        state.pausedUntil = Math.max(state.pausedUntil, until);
        return firstFailure;
    }

    /**
     * Queues a payload for resending, dropping the oldest ones beyond {@link #MAX_QUEUED_PAYLOADS}
     * and any older than {@link #MAX_QUEUE_AGE_MS}.
     */
    public synchronized void enqueue(String key, String payload) {
        State state = states.computeIfAbsent(key, k -> new State());
        prune(state);
        state.queue.addLast(new QueuedPayload(payload, clock.getAsLong()));
        while (state.queue.size() > MAX_QUEUED_PAYLOADS) {
            state.queue.removeFirst();
        }
    }

    /**
     * Starts resending the oldest queued payload. Pair every non-null result with {@link #completeDrain}.
     *
     * @return the payload to send, or null when paused, nothing is queued or a resend is already in flight
     */
    public synchronized String beginDrain(String key) {
        State state = states.get(key);
        if (state == null || state.inFlight != null || state.pausedUntil > clock.getAsLong()) {
            return null;
        }
        prune(state);
        state.inFlight = state.queue.peekFirst();
        return state.inFlight != null ? state.inFlight.payload : null;
    }

    /**
     * Finishes the resend started by {@link #beginDrain}: a delivered payload is removed from the queue,
     * otherwise it stays at the head to be retried after the next pause.
     */
    public synchronized void completeDrain(String key, boolean delivered) {
        State state = states.get(key);
        if (state == null || state.inFlight == null) {
            return;
        }
        if (delivered) {
            // Removed by identity: it may have been pushed out of the queue while in flight
            state.queue.remove(state.inFlight);
        }
        state.inFlight = null;
        removeIfIdle(key, state);
    }

    public synchronized void clear(String key) {
        states.remove(key);
    }

    public synchronized void clearAll() {
        states.clear();
    }

    private void prune(State state) {
        long cutoff = clock.getAsLong() - MAX_QUEUE_AGE_MS;
        while (!state.queue.isEmpty() && state.queue.peekFirst().enqueuedAt < cutoff) {
            state.queue.removeFirst();
        }
    }

    private void removeIfIdle(String key, State state) {
        if (state.pausedUntil == 0 && state.inFlight == null && state.queue.isEmpty()) {
            states.remove(key);
        }
    }
}

package haexporterplugin.utils;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import haexporterplugin.HAExporterConfig;
import haexporterplugin.HAExporterPlugin;
import haexporterplugin.data.HAConnection;
import haexporterplugin.data.PairingException;
import haexporterplugin.data.TokenCallback;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;
import okhttp3.internal.annotations.EverythingIsNonNull;

import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

@Slf4j
@Singleton
public class HomeAssistUtils {
    private static final String DATA_ENDPOINT = "/api/osrs-data/events";
    private static final String CONTENT_TYPE_JSON = "application/json; charset=utf-8";
    private static final String TOKEN_HEADER = "X-Osrs-Token";
    private static final String RETRY_AFTER_HEADER = "Retry-After";
    private static final String CONTENT_TYPE_HEADER = "Content-Type";
    private static final String APPLICATION_JSON = "application/json";
    private static final String VERSION_HEADER = "X-Osrs-Exporter-Version";

    // Limits for text an endpoint sends back during pairing (shown in the panel / dialogs)
    private static final int MAX_PAIR_NAME_LENGTH = 64;
    private static final int MAX_PAIR_ERROR_LENGTH = 200;
    private static final long MAX_PAIR_ERROR_BODY_BYTES = 8 * 1024;

    @Inject
    protected HAExporterConfig config;

    @Inject
    private ConfigUtils configUtils;

    @Inject
    private OkHttpClient okHttpClient;

    @Inject
    private ScheduledExecutorService executor;

    private @Inject Gson gson;

    private final ConnectionBackoff backoff = new ConnectionBackoff();

    // Set while the plugin is disabled, so late callbacks and scheduled drains don't queue or resend anything
    private volatile boolean stopped;

    public void startUp() {
        stopped = false;
    }

    public void shutDown() {
        stopped = true;
        backoff.clearAll();
    }

    public void sendMessage(String jsonPayload) {
        sendPayload(jsonPayload);
    }

    public long getPausedUntil(HAConnection connection) {
        return backoff.getPausedUntil(connectionKey(connection));
    }

    public int getQueuedCount(HAConnection connection) {
        return backoff.getQueuedCount(connectionKey(connection));
    }

    private void sendPayload(String jsonPayload) {
        List<HAConnection> connections = configUtils.getStoredConnections();

        for (HAConnection connection : connections) {
            String key = connectionKey(connection);
            if (!connection.isEnabled()) {
                log.debug("Skipping disabled connection: {}", connection.getDisplayName());
                backoff.clear(key);
                continue;
            }

            String filteredPayload = applyConnectionFilters(jsonPayload, connection);

            if (backoff.isPaused(key)) {
                // Events wait for the pause to end; plain snapshots are dropped, the next one carries the full state anyway
                if (payloadHasEvents(filteredPayload)) {
                    backoff.enqueue(key, filteredPayload);
                    log.debug("{} is paused, queued payload for retry", connection.getDisplayName());
                } else {
                    log.debug("{} is paused, dropped snapshot", connection.getDisplayName());
                }
                continue;
            }

            if (backoff.getQueuedCount(key) > 0 && payloadHasEvents(filteredPayload)) {
                // Line up behind the payloads still waiting to be resent, so events arrive in order
                backoff.enqueue(key, filteredPayload);
            } else {
                sendToConnection(connection, key, filteredPayload, false);
            }

            // Resends queued payloads once a pause has ended; a no-op when nothing is queued or a resend is in flight
            drainQueued(key);
        }
    }

    private void sendToConnection(HAConnection connection, String key, String payload, boolean drained) {
        String apiUrl = connection.getBaseUrl() + DATA_ENDPOINT;
        Request request = buildRequest(apiUrl, payload, connection.token);

        if (log.isDebugEnabled()){
            log.debug("{} ({}): {}",connection.getDisplayName(), apiUrl, payload);
        }

        okHttpClient.newCall(request).enqueue(createCallback(payload, connection, key, drained));
    }

    private void drainQueued(String key) {
        if (stopped) {
            return;
        }

        String payload = backoff.beginDrain(key);
        if (payload == null) {
            return;
        }

        HAConnection connection = findConnection(key);
        if (connection == null || !connection.isEnabled()) {
            // Removed or disabled since the payload was queued
            backoff.clear(key);
            return;
        }

        sendToConnection(connection, key, payload, true);
    }

    private void scheduleDrain(String key, long pausedUntil) {
        long delay = Math.max(0, pausedUntil - System.currentTimeMillis());
        executor.schedule(() -> {
            long stillPausedUntil = backoff.getPausedUntil(key);
            if (stillPausedUntil > 0) {
                // Woke up slightly early, or the pause was extended meanwhile
                scheduleDrain(key, stillPausedUntil);
            } else {
                drainQueued(key);
            }
        }, delay, TimeUnit.MILLISECONDS);
    }

    private HAConnection findConnection(String key) {
        for (HAConnection connection : configUtils.getStoredConnections()) {
            if (connectionKey(connection).equals(key)) {
                return connection;
            }
        }
        return null;
    }

    private static String connectionKey(HAConnection connection) {
        return connection.getBaseUrl() + '\n' + connection.getToken();
    }

    private boolean payloadHasEvents(String payload) {
        JsonObject root = gson.fromJson(payload, JsonObject.class);
        JsonElement events = root != null ? root.get("events") : null;
        return events != null && events.isJsonArray() && events.getAsJsonArray().size() > 0;
    }

    private String applyConnectionFilters(String jsonPayload, HAConnection connection) {
        boolean allDataEnabled = connection.isIncludeInventory()
                && connection.isIncludeEquipment()
                && connection.isIncludeLocation()
                && config.includeInventory()
                && config.includeEquipment()
                && config.includeLocation();

        boolean allEventsEnabled = connection.isIncludeLootEvents() && config.includeLootEvents()
                && connection.isIncludeDeathEvents() && config.includeDeathEvents()
                && connection.isIncludeLevelUpEvents() && config.includeLevelUpEvents()
                && connection.isIncludeAchievementDiaryEvents() && config.includeAchievementDiaryEvents()
                && connection.isIncludeCombatTaskEvents() && config.includeCombatTaskEvents()
                && connection.isIncludeSuperiorEvents() && config.includeSuperiorEvents()
                && connection.isIncludeCollectionLogEvents() && config.includeCollectionLogEvents();

        if (allDataEnabled && allEventsEnabled) {
            return jsonPayload;
        }

        JsonObject root = gson.fromJson(jsonPayload, JsonObject.class);

        if (!allDataEnabled && root.has("player")) {
            JsonObject player = root.getAsJsonObject("player");
            if (!connection.isIncludeInventory() || !config.includeInventory()) {
                player.remove("inventory");
            }
            if (!connection.isIncludeEquipment() || !config.includeEquipment()) {
                player.remove("equipment");
            }
            if (!connection.isIncludeLocation() || !config.includeLocation()) {
                player.remove("location");
            }
        }

        if (!allEventsEnabled && root.has("events")) {
            JsonArray filtered = new JsonArray();
            for (JsonElement element : root.getAsJsonArray("events")) {
                JsonObject event = element.getAsJsonObject();
                String type = event.has("type") ? event.get("type").getAsString() : "";
                if (shouldIncludeEvent(type, connection)) {
                    filtered.add(event);
                }
            }
            root.add("events", filtered);
        }

        return gson.toJson(root);
    }

    private boolean shouldIncludeEvent(String type, HAConnection connection) {
        switch (type) {
            case "loot":
            case "pkLoot":
                return connection.isIncludeLootEvents() && config.includeLootEvents();
            case "death":
                return connection.isIncludeDeathEvents() && config.includeDeathEvents();
            case "levelUp":
                return connection.isIncludeLevelUpEvents() && config.includeLevelUpEvents();
            case "achievementDiary":
                return connection.isIncludeAchievementDiaryEvents() && config.includeAchievementDiaryEvents();
            case "combatTask":
                return connection.isIncludeCombatTaskEvents() && config.includeCombatTaskEvents();
            case "superiorSpawn":
                return connection.isIncludeSuperiorEvents() && config.includeSuperiorEvents();
            case "collectionLog":
                return connection.isIncludeCollectionLogEvents() && config.includeCollectionLogEvents();
            default:
                // clientShutdown and any unknown events are always forwarded
                return true;
        }
    }

    Request buildRequest(String apiUrl, String jsonPayload, String token) {
        RequestBody requestBody = RequestBody.create(MediaType.parse(CONTENT_TYPE_JSON), jsonPayload);

        return new Request.Builder()
                .url(Objects.requireNonNull(HttpUrl.parse(apiUrl)))
                .header(TOKEN_HEADER, token)
                .header(CONTENT_TYPE_HEADER, APPLICATION_JSON)
                .header(VERSION_HEADER, HAExporterPlugin.PLUGIN_VERSION)
                .post(requestBody)
                .build();
    }

    private Callback createCallback(String jsonPayload, HAConnection connection, String key, boolean drained) {
        return new Callback() {
            @Override
            @EverythingIsNonNull
            public void onFailure(Call call, IOException e) {
                retryLater(connection, key, jsonPayload, drained, null, e.toString());
            }

            @Override
            @EverythingIsNonNull
            public void onResponse(Call call, Response response) {
                try {
                    int code = response.code();
                    switch (ConnectionBackoff.classify(code)) {
                        case SUCCESS:
                            backoff.recordSuccess(key);
                            if (drained) {
                                backoff.completeDrain(key, true);
                            }
                            drainQueued(key);
                            break;
                        case UNAUTHORIZED:
                            log.warn("Received 401 Unauthorized from {}. Disabling connection.", connection.getDisplayName());
                            disableConnection(connection, "Unauthorized (401): Token may have been revoked.");
                            break;
                        case GONE:
                            log.warn("Received 410 Gone from {}. Disabling connection.", connection.getDisplayName());
                            disableConnection(connection, "Endpoint gone (410): this endpoint no longer accepts data.");
                            break;
                        case RETRY_AFTER:
                            Long retryAt = ConnectionBackoff.parseRetryAfter(response.header(RETRY_AFTER_HEADER), System.currentTimeMillis());
                            retryLater(connection, key, jsonPayload, drained, retryAt, "HTTP " + code);
                            break;
                        case BACKOFF:
                            retryLater(connection, key, jsonPayload, drained, null, "HTTP " + code);
                            break;
                        default:
                            log.debug("{} rejected a payload with HTTP {}, not retrying it", connection.getDisplayName(), code);
                            if (drained) {
                                backoff.completeDrain(key, true);
                                drainQueued(key);
                            }
                            break;
                    }
                } finally {
                    response.close();
                }
            }
        };
    }

    /**
     * Pauses the connection after a failed delivery and keeps the payload for a retry when it carries events.
     * Receivers dedupe on eventId, so resending a payload that did arrive (e.g. after a timeout) is harmless.
     */
    private void retryLater(HAConnection connection, String key, String payload, boolean drained, Long retryAt, String cause) {
        if (stopped) {
            log.debug("Could not deliver data to {} ({}) after the plugin was disabled, not retrying", connection.getDisplayName(), cause);
            return;
        }

        boolean firstFailure = retryAt != null
                ? backoff.recordRetryAfter(key, retryAt)
                : backoff.recordFailure(key);
        long pausedUntil = backoff.getPausedUntil(key);

        if (drained) {
            backoff.completeDrain(key, false);
        } else if (payloadHasEvents(payload)) {
            backoff.enqueue(key, payload);
        }

        long pauseSeconds = (Math.max(0, pausedUntil - System.currentTimeMillis()) + 999) / 1000;
        if (firstFailure) {
            log.warn("Could not deliver data to {} ({}). Pausing for {}s before retrying.", connection.getDisplayName(), cause, pauseSeconds);
        } else {
            log.debug("Could not deliver data to {} ({}). Pausing for {}s before retrying.", connection.getDisplayName(), cause, pauseSeconds);
        }

        scheduleDrain(key, pausedUntil);
    }

    private void disableConnection(HAConnection connection, String reason) {
        backoff.clear(connectionKey(connection));

        List<HAConnection> connections = configUtils.getStoredConnections();
        for (HAConnection c : connections) {
            if (c.getBaseUrl().equals(connection.getBaseUrl())
                    && c.getToken().equals(connection.getToken())) {
                c.setEnabled(false);
                c.setDisabledReason(reason);
                break;
            }
        }
        configUtils.saveConnections(connections);
    }

    public void getToken(String baseUrl, String code, TokenCallback callback) {
        String apiUrl = baseUrl + "/api/osrs-data/pair";

        JsonObject jsonObject = new JsonObject();
        jsonObject.addProperty("code", code);

        String jsonPayload = gson.toJson(jsonObject);

        RequestBody requestBody = RequestBody.create(MediaType.get("application/json; charset=utf-8"), jsonPayload);

        Request request = new Request.Builder()
                .url(apiUrl)
                .header(VERSION_HEADER, HAExporterPlugin.PLUGIN_VERSION)
                .post(requestBody)
                .build();

        okHttpClient.newCall(request).enqueue(new Callback() {

            @Override
            public void onFailure(@Nonnull Call call, @Nonnull IOException e) {
                log.error("Error acquiring token", e);
                callback.onFailure(e);
            }

            @Override
            public void onResponse(@Nonnull Call call, @Nonnull Response response) {
                try (ResponseBody body = response.body()) {

                    if (!response.isSuccessful()) {
                        String serverError = extractPairError(gson, readPairErrorBody(response));
                        callback.onFailure(new PairingException("Unexpected response " + response, serverError));
                        return;
                    }

                    if (body == null) {
                        callback.onFailure(new IOException("Empty response body"));
                        return;
                    }

                    String responseBody = body.string();
                    JsonObject jsonResponse = gson.fromJson(responseBody, JsonObject.class);

                    String token = jsonResponse.get("token").getAsString();
                    callback.onSuccess(token, parsePairName(jsonResponse));

                } catch (Exception e) {
                    callback.onFailure(e);
                }
            }
        });
    }

    // Best effort: an unreadable error body just means the generic failure message is shown.
    @Nullable
    private static String readPairErrorBody(Response response) {
        try {
            return response.peekBody(MAX_PAIR_ERROR_BODY_BYTES).string();
        } catch (Exception e) {
            return null;
        }
    }

    // Optional "name" from a successful pair response, used as the connection's default friendly name.
    @Nullable
    static String parsePairName(JsonObject pairResponse) {
        return sanitizeServerText(getStringField(pairResponse, "name"), MAX_PAIR_NAME_LENGTH, false);
    }

    // Optional "error" from a failed pair response. Returns null for anything unusable (non-JSON, no/non-string "error").
    @Nullable
    static String extractPairError(Gson gson, @Nullable String body) {
        if (body == null || body.trim().isEmpty()) {
            return null;
        }

        try {
            JsonElement root = gson.fromJson(body, JsonElement.class);
            if (root == null || !root.isJsonObject()) {
                return null;
            }
            return sanitizeServerText(getStringField(root.getAsJsonObject(), "error"), MAX_PAIR_ERROR_LENGTH, true);
        } catch (RuntimeException e) {
            // Not JSON, e.g. an HTML error page from a reverse proxy
            return null;
        }
    }

    // Text from the network ends up in Swing labels and dialogs, which render text starting with "<html>" as HTML.
    // Strips control characters (optionally keeping '\n') and angle brackets, trims and caps the length. Blank -> null.
    @Nullable
    static String sanitizeServerText(@Nullable String text, int maxLength, boolean keepNewlines) {
        if (text == null) {
            return null;
        }

        StringBuilder sb = new StringBuilder(text.length());
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c == '<' || c == '>' || (Character.isISOControl(c) && !(keepNewlines && c == '\n'))) {
                continue;
            }
            sb.append(c);
        }

        String result = sb.toString().trim();
        if (result.length() > maxLength) {
            // Don't split a surrogate pair at the cut
            int end = Character.isHighSurrogate(result.charAt(maxLength - 1)) ? maxLength - 1 : maxLength;
            result = result.substring(0, end).trim();
        }

        return result.isEmpty() ? null : result;
    }

    @Nullable
    private static String getStringField(JsonObject object, String key) {
        JsonElement element = object.get(key);
        if (element == null || !element.isJsonPrimitive() || !element.getAsJsonPrimitive().isString()) {
            return null;
        }
        return element.getAsString();
    }
}

package haexporterplugin.utils;

import com.google.common.net.UrlEscapers;
import lombok.Value;
import lombok.experimental.UtilityClass;

@UtilityClass
public class ReplacementUtils {

    public Evaluable ofText(String text) {
        return new Text(text);
    }

    public Evaluable ofLink(String text, String link) {
        return link != null ? new TextWithLink(text, link) : ofText(text);
    }

    public Evaluable ofWiki(String text, String searchPhrase) {
        return ofLink(text, "https://oldschool.runescape.wiki/w/Special:Search?search=" + UrlEscapers.urlPathSegmentEscaper().escape(searchPhrase));
    }

    public Evaluable ofWiki(String phrase) {
        return ofWiki(phrase, phrase);
    }

    @Value
    private static class Text implements Evaluable {
        String text;

        @Override
        public String evaluate(boolean rich) {
            return text;
        }
    }

    @Value
    private static class TextWithLink implements Evaluable {
        String text;
        String link;

        @Override
        public String evaluate(boolean rich) {
            return rich ? String.format("[%s](%s)", text, link) : text;
        }
    }

}

package haexporterplugin.utils;

import com.google.common.hash.HashCode;
import haexporterplugin.enums.AccountType;
import lombok.experimental.UtilityClass;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;
import org.apache.commons.lang3.StringUtils;
import org.jetbrains.annotations.NotNull;

import javax.annotation.Nullable;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import java.util.stream.Stream;


@Slf4j
@UtilityClass
public class Utils {
    public AccountType getAccountType(Client client) {
        return AccountType.get(client.getVarbitValue(VarbitID.IRONMAN));
    }

    // DO NOT CHANGE: changing the salt changes every user's accountHash, so receivers would see every account as new.
    private final byte[] ACCOUNT_HASH_SALT = "HAExporter-AccountHash-v1".getBytes(StandardCharsets.UTF_8);

    /**
     * Same approach as Utils#dinkHash in Dink Plugin, but with our own salt.
     * source: <a href="https://github.com/pajlads/DinkPlugin/blob/master/src/main/java/dinkplugin/util/Utils.java"></a>
     *
     * @param accountHash the value of {@link Client#getAccountHash()}
     * @return a salted SHA-224 hex digest, or null when not logged in (-1) or SHA-224 is unavailable
     */
    @Nullable
    public String accountHash(long accountHash) {
        if (accountHash == -1) return null;

        MessageDigest digest;
        try {
            digest = MessageDigest.getInstance("SHA-224");
        } catch (NoSuchAlgorithmException e) {
            log.warn("Account hash could not be computed", e);
            return null;
        }

        byte[] input = ByteBuffer.allocate(8 + ACCOUNT_HASH_SALT.length)
                .putLong(accountHash)
                .put(ACCOUNT_HASH_SALT)
                .array();
        return HashCode.fromBytes(digest.digest(input)).toString();
    }

    private final Pattern DELIM = Pattern.compile("[,;\\n]");

    public Stream<String> readDelimited(String value) {
        if (value == null) return Stream.empty();
        return DELIM.splitAsStream(value)
                .map(String::trim)
                .filter(StringUtils::isNotEmpty);
    }

    /**
     * Converts simple patterns (asterisk is the only special character) into regexps.
     *
     * @param pattern a simple pattern (asterisks are wildcards, and the rest is a string literal)
     * @return a compiled regular expression associated with the simple pattern
     */
    @Nullable
    public Pattern regexify(@NotNull String pattern) {
        final int len = pattern.length();
        final StringBuilder sb = new StringBuilder(len + 2 + 4);
        int startIndex = 0;

        if (!pattern.startsWith("*")) {
            sb.append('^');
        } else {
            startIndex++;
        }

        int i;
        while ((i = pattern.indexOf('*', startIndex)) >= 0) {
            String section = pattern.substring(startIndex, i);
            sb.append(Pattern.quote(section));
            sb.append(".*");
            startIndex = i + 1;
        }

        if (startIndex < len) {
            sb.append(Pattern.quote(pattern.substring(startIndex)));
            sb.append('$');
        }

        try {
            return Pattern.compile(sb.toString(), Pattern.CASE_INSENSITIVE);
        } catch (PatternSyntaxException e) {
            log.warn("Failed to parse pattern: {}", pattern, e);
            return null;
        }
    }
}

package haexporterplugin.utils;

import com.google.common.collect.ImmutableSet;
import haexporterplugin.data.ItemData;
import lombok.experimental.UtilityClass;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;

import java.util.*;
import java.util.function.BinaryOperator;
import java.util.function.Function;

import static net.runelite.api.gameval.ItemID.*;

@Slf4j
@UtilityClass
public class ItemUtils {

    private final Set<Integer> NEVER_KEPT_ITEMS = ImmutableSet.of(
            BH_CLUE_BOX, LOOTING_BAG, FLAMTAER_BAG, II_JAR_GENERATOR,
            DAMNED_AMULET_DEGRADED, RING_OF_CHAROS, RING_OF_CHAROS_UNLOCKED,
            WILD_CAVE_BRACELET_CHARGED, WILD_CAVE_BRACELET_UNCHARGED,
            ANMA_50_REWARD, ANMA_30_REWARD, FAIRY_ENCHANTED_SECATEURS, II_MAGIC_BUTTERFLY_NET,
            GAUNTLETS_OF_COOKING, GAUNTLETS_OF_GOLDSMITHING, GAUNTLETS_OF_CHAOS, STEEL_GAUNTLETS,
            FRISD_JESTER_HAT, FRISD_JESTER_TOP, FRISD_JESTER_LEGS, FRISD_JESTER_BOOTS,
            LUNAR_HELMET, LUNAR_TORSO, LUNAR_LEGS, LUNAR_GLOVES, LUNAR_BOOTS,
            LUNAR_CAPE, LUNAR_AMULET, LUNAR_RING, LUNAR_MOONCLAN_LIMINAL_STAFF,
            LEAGUE_3_ADAMANT_TROPHY, LEAGUE_3_BRONZE_TROPHY, LEAGUE_3_DRAGON_TROPHY,
            LEAGUE_3_IRON_TROPHY, LEAGUE_3_MITHRIL_TROPHY, LEAGUE_3_RUNE_TROPHY, LEAGUE_3_STEEL_TROPHY,
            LEAGUE_5_ADAMANT_TROPHY, LEAGUE_5_BRONZE_TROPHY, LEAGUE_5_DRAGON_TROPHY,
            LEAGUE_5_IRON_TROPHY, LEAGUE_5_MITHRIL_TROPHY, LEAGUE_5_RUNE_TROPHY, LEAGUE_5_STEEL_TROPHY,
            TRAILBLAZER_ADAMANT_TROPHY, TRAILBLAZER_BRONZE_TROPHY, TRAILBLAZER_DRAGON_TROPHY, TRAILBLAZER_IRON_TROPHY,
            TRAILBLAZER_MITHRIL_TROPHY, TRAILBLAZER_RUNE_TROPHY, TRAILBLAZER_STEEL_TROPHY,
            TWISTED_ADAMANT_TROPHY, TWISTED_BRONZE_TROPHY, TWISTED_DRAGON_TROPHY, TWISTED_IRON_TROPHY,
            TWISTED_MITHRIL_TROPHY, TWISTED_RUNE_TROPHY, TWISTED_STEEL_TROPHY
    );

    private final BinaryOperator<ItemData> SUM_ITEM_QUANTITIES = (a, b) -> new ItemData(a.getName(), a.getId(), a.getGePrice(), a.getHaPrice(), a.getQuantity() + b.getQuantity());
    private final BinaryOperator<ItemData> SUM_ITEM_STACK_QUANTITIES = (a, b) -> new ItemData(a.getName(), a.getId(), a.getGePrice(), a.getHaPrice(), a.getQuantity() + b.getQuantity());

    public List<ItemData> getInventoryItems(Client client, ItemManager itemManager)
    {
        List<ItemData> inventoryItems = new ArrayList<>();

        var invContainer = client.getItemContainer(InventoryID.INV);
        if (invContainer != null) {
            var items = invContainer.getItems();
            // Array index is the inventory slot (0-27, left to right, top to bottom)
            for (int slotIndex = 0; slotIndex < items.length; slotIndex++) {
                var item = items[slotIndex];
                if (item.getId() <= 0) continue; // Skip empty slots
                ItemComposition ic = itemManager.getItemComposition(item.getId());
                ItemData itemData = createItemData(ic, item.getQuantity(), itemManager);
                itemData.setInventorySlot(slotIndex);
                inventoryItems.add(itemData);
            }
        }

        return inventoryItems;
    }

    public List<ItemData> getEquippedItems(Client client, ItemManager itemManager){
        List<ItemData> equipmentItems = new ArrayList<>();

        var equipContainer = client.getItemContainer(InventoryID.WORN);
        if (equipContainer != null) {
            var items = equipContainer.getItems();
            for (int slotIndex = 0; slotIndex < items.length; slotIndex++) {
                var item = items[slotIndex];
                if (item.getId() <= 0) continue; // Skip empty slots
                ItemComposition ic = itemManager.getItemComposition(item.getId());
                ItemData itemData = createItemData(ic, item.getQuantity(), itemManager);

                // Map slot index to EquipmentInventorySlot enum and get its name
                if (slotIndex < EquipmentInventorySlot.values().length) {
                    String slotName = String.valueOf(slotIndex);
                    try {
                        slotName = net.runelite.api.EquipmentInventorySlot.values()[slotIndex].name();
                    } catch (Exception e) {
                        log.warn("Could not map slot index {} to EquipmentInventorySlot", slotIndex);
                    }
                    itemData.setEquipmentSlot(slotName);
                }
                equipmentItems.add(itemData);
            }
        }
        return equipmentItems;
    }

    public ItemData createItemData(ItemComposition ic, int quantity, ItemManager itemManager){
        return new ItemData(
                ic.getName(),
                ic.getId(),
                getPrice(ic.getId(), itemManager),
                ic.getHaPrice(),
                quantity
        );
    }

    public boolean isItemNeverKeptOnDeath(int itemId) {
        // https://oldschool.runescape.wiki/w/Items_Kept_on_Death#Items_that_are_never_kept
        // https://oldschoolrunescape.fandom.com/wiki/Items_Kept_on_Death#Items_that_are_never_kept
        return NEVER_KEPT_ITEMS.contains(itemId);
    }

    public long getPrice(int id, ItemManager itemManager){
        return itemManager.getItemPrice(id);
    }

    public long getStackGePrice(ItemData items){
        List<ItemData> itemList = new ArrayList<>(1);
        itemList.add(items);
        return getStackGePrice(itemList);
    }

    public long getStackGePrice(List<ItemData> items){
        long totalPrice = 0;
        for (ItemData item : items){
            long stackPrice = item.getGePrice() * item.getQuantity();
            totalPrice += stackPrice;
        }
        return totalPrice;
    }

    public <K, V> Map<K, V> reduce(Iterable<V> items, Function<V, K> deriveKey, BinaryOperator<V> aggregate) {
        final Map<K, V> map = new LinkedHashMap<>();
        items.forEach(v -> map.merge(deriveKey.apply(v), v, aggregate));
        return map;
    }

    public Map<Integer, ItemData> reduceItems(Iterable<ItemData> items) {
        return reduce(items, ItemData::getId, SUM_ITEM_QUANTITIES);
    }

    public List<ItemData> itemsToItemDataList(Collection<ItemStack> itemStacks, ItemManager itemManager){
        List<ItemData> itemDataList = new ArrayList<>(itemStacks.size());
        for (ItemStack itemStack: itemStacks ){
            itemDataList.add(itemStackToItemData(itemStack, itemManager));
        }
        return itemDataList;
    }

    public ItemData itemStackToItemData(ItemStack itemStack, ItemManager itemManager){
        ItemComposition ic = itemManager.getItemComposition(itemStack.getId());
        return createItemData(ic, itemStack.getQuantity(), itemManager);
    }

    public Collection<ItemData> reduceItemStack(Iterable<ItemData> items) {
        return reduce(items, ItemData::getId, SUM_ITEM_STACK_QUANTITIES).values();
    }
}

