import net.runelite.api.events.GameStateChanged;

import javax.inject.Singleton;
import java.util.*;

import static net.runelite.api.Experience.MAX_REAL_LEVEL;

@Slf4j
@Singleton
public class LevelNotifier extends BaseNotifier {
    private static final Set<WorldType> SPECIAL_WORLDS = EnumSet.of(WorldType.PVP_ARENA, WorldType.QUEST_SPEEDRUNNING, WorldType.BETA_WORLD, WorldType.NOSAVE_MODE, WorldType.TOURNAMENT_WORLD, WorldType.DEADMAN, WorldType.SEASONAL);
    public static final int LEVEL_FOR_MAX_XP = Experience.MAX_VIRT_LEVEL + 1; // 127
    private static final int SKILL_COUNT = Skill.values().length;
    private static final String COMBAT_NAME = "Combat";
    private final Map<String, Integer> currentLevels = new HashMap<>();
    private final Map<String, Integer> previousLevels = new HashMap<>();
    private final Map<Skill, Integer> currentXp = new EnumMap<>(Skill.class);
    static final int INIT_GAME_TICKS = 1; // ~10s
    private Set<WorldType> specialWorldType = null;
    // Ticks since login or the last hop, while waiting to take the baseline
    private int ticksSinceReset = 0;

    private void updateSkillsFromGameState() {
        for (Skill skill : Skill.values()) {
            int xp = client.getSkillExperience(skill);
            int level = client.getRealSkillLevel(skill);
            if (level >= MAX_REAL_LEVEL) {
                level = getLevel(xp);
            }
            currentLevels.put(skill.getName(), level);
            currentXp.put(skill, xp);
        }
        currentLevels.put(COMBAT_NAME, calculateCombatLevel());
    }

    private void initLevels() {
        updateSkillsFromGameState();
        previousLevels.putAll(currentLevels);
        this.specialWorldType = getSpecialWorldTypes();
    }

    private int getLevel(int xp) {
        // treat 200M XP as level 127
        if (xp >= Experience.MAX_SKILL_XP)
            return LEVEL_FOR_MAX_XP;

        // log(n) operation to support virtual levels
        return Experience.getLevelForXp(xp);
    }

    private int calculateCombatLevel() {
        return Experience.getCombatLevel(
                getRealLevel(Skill.ATTACK),
                getRealLevel(Skill.STRENGTH),
                getRealLevel(Skill.DEFENCE),
                getRealLevel(Skill.HITPOINTS),
                getRealLevel(Skill.MAGIC),
                getRealLevel(Skill.RANGED),
                getRealLevel(Skill.PRAYER)
        );
    }

    private int getRealLevel(Skill skill) {
        Integer cachedLevel = currentLevels.get(skill.getName());
        return cachedLevel != null
                ? Math.min(cachedLevel, MAX_REAL_LEVEL)
                : client.getRealSkillLevel(skill);
    }

    private Set<WorldType> getSpecialWorldTypes() {
        var world = client.getWorldType().clone();
        world.retainAll(SPECIAL_WORLDS); // O(1)
        return world;
    }

    private List<LevelEvent> detectAndUpdateLevelChanges() {
        List<LevelEvent> changedLevels = new ArrayList<LevelEvent>();
        for (String skillName : currentLevels.keySet()) {
            int currentLevel = currentLevels.get(skillName);
            int previousLevel = previousLevels.getOrDefault(skillName, currentLevel);
            if (currentLevel != previousLevel) {
                previousLevels.put(skillName, currentLevel);
                if (shouldSend(skillName, currentLevel, config.levelMinValue(),
                        config.levelInterval(), config.levelIncludeVirtual(), config.levelIncludeCombat())) {
                    changedLevels.add(new LevelEvent(skillName, currentLevel));
                }
            }
        }
        return changedLevels;
    }

    static boolean shouldSend(String skillName, int level, int minLevel, int interval, boolean includeVirtual, boolean includeCombat) {
        boolean combat = COMBAT_NAME.equals(skillName);
        if (combat && !includeCombat) return false;
        if (!combat && level > MAX_REAL_LEVEL && !includeVirtual) return false;
        if (level < minLevel) return false;
        return level == MAX_REAL_LEVEL || level % Math.max(interval, 1) == 0;
    }

    private Stats buildStats() {
        Map<String, SkillInfo> skillsMap = new LinkedHashMap<>();
        for (Skill runeLiteSkill : Skill.values()) {
            String skillName = runeLiteSkill.getName();
            Integer xp = currentXp.get(runeLiteSkill);
            Integer level = currentLevels.get(skillName);
            if (xp != null && level != null) {
                skillsMap.put(skillName, new SkillInfo(xp, level));
            }
        }
        return new Stats(skillsMap);
    }

    public void onGameStateChanged(GameStateChanged event) {
        // A hop or re-login can switch to a character with different stats (e.g. a special world or another
        // account), so take a new baseline instead of reporting the difference as level-ups
        if (event.getGameState() == GameState.HOPPING || event.getGameState() == GameState.LOGIN_SCREEN) {
            currentLevels.clear();
            previousLevels.clear();
            currentXp.clear();
            ticksSinceReset = 0;
        }
    }

    public void onTick(){
        // Give the client a moment after login or a hop to report the new character's stats
        if (previousLevels.isEmpty() && ++ticksSinceReset > INIT_GAME_TICKS) {
            initLevels();
            return;
        }

        updateSkillsFromGameState();
        List<LevelEvent> changedLevels = detectAndUpdateLevelChanges();

        Stats stats = buildStats();
        messageBuilder.setData("stats", stats);

        if (!changedLevels.isEmpty()) {
            messageBuilder.addEvent("levelUp", changedLevels);
            tickUtils.sendNow();
        }
    }
}

package haexporterplugin.notifiers;

import haexporterplugin.data.PlayerLocation;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

@Slf4j
public class LocationNotifier extends BaseNotifier{
    public void onTick()
    {
        Actor player = client.getLocalPlayer();
        LocalPoint localPoint = player.getLocalLocation();
        WorldView worldView = player.getWorldView();
        int worldViewId = worldView.getId();
        boolean isOnBoat = worldViewId != WorldView.TOPLEVEL;
        WorldPoint worldPoint;
        if (isOnBoat) {
            WorldEntity worldEntity = client.getTopLevelWorldView().worldEntities().byIndex(worldViewId);
            worldPoint = WorldPoint.fromLocalInstance(client, worldEntity.getLocalLocation());
        } else {
            worldPoint = WorldPoint.fromLocalInstance(client, localPoint);
        }

        PlayerLocation playerLocation = new PlayerLocation(worldPoint, isOnBoat);

        messageBuilder.setData("location", playerLocation);
    }
}

package haexporterplugin.notifiers;

import com.google.common.annotations.VisibleForTesting;
import haexporterplugin.data.CollectionData;
import haexporterplugin.utils.KillCountTracker;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.ItemComposition;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

import javax.annotation.Nullable;
import javax.inject.Inject;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
public class CollectionNotifier extends BaseNotifier {

    private @Inject ItemManager itemManager;
    private @Inject ClientThread clientThread;
    private @Inject KillCountTracker killCountTracker;

    private static final String COLLECTION_LOG_TITLE = "Collection log";
    private static final String NEW_ITEM_PREFIX = "New item:";

    // Value of the in-game "Collection log - New addition notification" setting that only uses chat (no popup)
    private static final int NEW_ITEM_NOTIFICATION_CHAT_ONLY = 1;

    // Item definitions scanned per client tick while building the name lookup
    private static final int ITEM_LOOKUP_BATCH_SIZE = 2000;

    private static final Pattern COLLECTION_LOG_PATTERN = Pattern.compile(
            "New item added to your collection log: (?<itemName>.+)"
    );

    private static final Pattern KILL_COUNT_PATTERN = Pattern.compile(
            "Your (?<key>.+) (?:kill|success|harvest|lap|completion) count is: (?<value>[\\d,]+)\\b"
    );

    private static final Pattern KILL_COUNT_PATTERN_SECONDARY = Pattern.compile(
            "Your (?:completed )?(?<key>.+?) count is: (?<value>[\\d,]+)\\b"
    );

    // Lowercase item name -> canonical item id, built in batches after login.
    private Map<String, Integer> itemIdByName = null;
    private Map<String, Integer> partialItemIdByName = null;
    private int nextItemId = 0;

    private boolean notificationStarted = false;

    public void onGameStateChanged(GameStateChanged event) {
        switch (event.getGameState()) {
            case LOGGED_IN:
                startItemNameLookup();
                break;
            case HOPPING:
            case LOGIN_SCREEN:
                killCountTracker.reset();
                break;
        }
    }

    // Popup mode: the collection log popup is driven by the same client scripts that draw the on-screen notification.
    public void onScript(ScriptPreFired event) {
        switch (event.getScriptId()) {
            case ScriptID.NOTIFICATION_START:
                notificationStarted = true;
                break;
            case ScriptID.NOTIFICATION_DELAY:
                if (!notificationStarted) return;
                notificationStarted = false;

                String itemName = parsePopupItemName(
                        client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE),
                        client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN));
                if (itemName != null) {
                    clientThread.invokeAtTickEnd(() -> handleCollectionLog(itemName));
                }
                break;
        }
    }

    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE) return;

        String message = Text.removeTags(event.getMessage());
        Integer killCount = parseKillCount(message);
        if (killCount != null) {
            killCountTracker.onKillCount(killCount, client.getTickCount());
            return;
        }

        // Chat-only mode shows no popup, so the chat message is the only signal; otherwise the popup is used,
        // which keeps an item from being reported twice
        if (client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) != NEW_ITEM_NOTIFICATION_CHAT_ONLY) return;

        Matcher matcher = COLLECTION_LOG_PATTERN.matcher(message);
        if (matcher.matches()) {
            String itemName = matcher.group("itemName").trim();
            // At tick end, so a kill count or loot from the same tick is seen first
            clientThread.invokeAtTickEnd(() -> handleCollectionLog(itemName));
        }
    }

    /**
     * @return the item name from a "Collection log" popup, or null for any other popup
     */
    @Nullable
    @VisibleForTesting
    static String parsePopupItemName(@Nullable String title, @Nullable String body) {
        if (!COLLECTION_LOG_TITLE.equalsIgnoreCase(title) || body == null) return null;

        String text = Text.removeTags(body);
        if (!text.startsWith(NEW_ITEM_PREFIX)) return null;

        String itemName = text.substring(NEW_ITEM_PREFIX.length()).trim();
        return itemName.isEmpty() ? null : itemName;
    }

    @Nullable
    @VisibleForTesting
    static Integer parseKillCount(String message) {
        Matcher matcher = KILL_COUNT_PATTERN.matcher(message);
        if (!matcher.find()) {
            matcher = KILL_COUNT_PATTERN_SECONDARY.matcher(message);
            if (!matcher.find()) return null;
        }
        try {
            return Integer.parseInt(matcher.group("value").replace(",", ""));
        } catch (NumberFormatException e) {
            return null;
        }
    }

    private void handleCollectionLog(String itemName) {
        int itemId = resolveItemId(itemName);
        long value = itemId > 0 ? itemManager.getItemPrice(itemId) : 0L;

        // Items without a price (pets, untradeables, unresolved names) are always sent.
        if (value > 0 && value < config.clogMinValue()) {
            log.debug("Skipping collection log item below minimum value: {} ({} gp)", itemName, value);
            return;
        }

        Integer killCount = killCountTracker.getKillCount(client.getTickCount());

        log.debug("Collection log item obtained: {} (id: {}, value: {}, kc: {})", itemName, itemId, value, killCount);

        messageBuilder.addEvent("collectionLog", new CollectionData(itemName, itemId, value, killCount));
        tickUtils.sendNow();
    }

    private int resolveItemId(String itemName) {
        // Normally already built after login; finish it now if an item shows up before that
        while (!buildItemNameLookupBatch()) {
            // keep scanning
        }
        return itemIdByName.getOrDefault(itemName.toLowerCase(), -1);
    }

    // Scanning every item definition at once stalls the client, so it's spread over client ticks
    private void startItemNameLookup() {
        if (itemIdByName != null || partialItemIdByName != null) return;
        clientThread.invokeLater(this::buildItemNameLookupBatch);
    }

    /**
     * @return true once the lookup is complete
     */
    private boolean buildItemNameLookupBatch() {
        if (itemIdByName != null) return true;
        if (partialItemIdByName == null) {
            partialItemIdByName = new HashMap<>();
            nextItemId = 0;
        }

        int count = client.getItemCount();
        int end = Math.min(count, nextItemId + ITEM_LOOKUP_BATCH_SIZE);
        for (int id = nextItemId; id < end; id++) {
            int canonical = itemManager.canonicalize(id);
            if (canonical != id) continue;

            ItemComposition composition = itemManager.getItemComposition(canonical);
            if (composition.getNote() != -1 || composition.getPlaceholderTemplateId() != -1) continue;

            String name = composition.getName();
            if (name == null || name.isEmpty() || "null".equals(name)) continue;

            partialItemIdByName.putIfAbsent(name.toLowerCase(), canonical);
        }
        nextItemId = end;
        if (end < count) return false;

        itemIdByName = partialItemIdByName;
        partialItemIdByName = null;
        return true;
    }
}

package haexporterplugin.notifiers;

import com.google.common.annotations.VisibleForTesting;
import haexporterplugin.data.ItemData;
import haexporterplugin.enums.AccountType;
import haexporterplugin.enums.Danger;
import haexporterplugin.enums.ExceptionalDeath;
import haexporterplugin.events.DeathEvent;
import haexporterplugin.utils.ItemUtils;
import haexporterplugin.utils.Utils;
import haexporterplugin.utils.WorldUtils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.ParamID;
import net.runelite.api.Player;
import net.runelite.api.SkullIcon;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.NPCManager;
import org.apache.commons.lang3.ArrayUtils;
import org.apache.commons.lang3.StringUtils;
import org.apache.commons.lang3.tuple.Pair;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.lang.ref.WeakReference;
import java.util.*;
import java.util.function.BiFunction;
import java.util.function.BiPredicate;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.stream.Collectors;

/**
 * Code based on DeathNotifier in Dink Plugin
 * source: <a href="https://github.com/pajlads/DinkPlugin/blob/master/src/main/java/dinkplugin/notifiers/DeathNotifier.java"></a>
 */

@Slf4j
@Singleton
public class DeathNotifier extends BaseNotifier {

    private static final String ATTACK_OPTION = "Attack";

    private static final String TOA_DEATH_MSG = "You failed to survive the Tombs of Amascut";

    private static final String TOB_DEATH_MSG = "Your party has failed";

    private static final String FORTIS_DOOM_MSG = "You have been doomed!";

    /**
     * @see <a href="https://github.com/Joshua-F/cs2-scripts/blob/master/scripts/%5Bclientscript,tob_hud_portal%5D.cs2">CS2 Reference</a>
     */
    private static final int TOB_HUB_PORTAL_SCRIPT = 2307;

    /**
     * Checks whether the actor is alive and interacting with the specified player.
     */
    private static final BiPredicate<Player, Actor> INTERACTING;

    /**
     * Checks whether a NPC is a valid candidate to be our killer.
     */
    private static final Predicate<NPCComposition> NPC_VALID;

    /**
     * Orders NPCs by their likelihood of being our killer.
     */
    private static final BiFunction<NPCManager, Player, Comparator<NPC>> NPC_COMPARATOR;

    /**
     * Orders actors by their likelihood of being the killer of the specified player.
     */
    private static final Function<Player, Comparator<Player>> PK_COMPARATOR;

    @Inject
    private ItemManager itemManager;

    @Inject
    private NPCManager npcManager;

    /**
     * Tracks the last {@link Actor} our local player interacted with,
     * for the purposes of attributing deaths to particular {@link Player}'s.
     * <p>
     * Note: this is wrapped in a weak reference to allow garbage collection,
     * for example if the {@link Actor} despawns.
     * As a result, the underlying reference can be null.
     *
     * @see #identifyKiller()
     */
    private WeakReference<Actor> lastTarget = new WeakReference<>(null);

    public void onActorDeath(ActorDeath actor) {
        boolean self = client.getLocalPlayer() == actor.getActor();

        if (self)
            handleNotify(null);

        if (self || actor.getActor() == lastTarget.get())
            lastTarget = new WeakReference<>(null);
    }

    public void onGameMessage(String message) {
        var player = client.getLocalPlayer();
        if (message.equals(FORTIS_DOOM_MSG) && player.getHealthRatio() > 0 && Objects.requireNonNull(WorldUtils.getLocation(client, player)).getRegionID() == WorldUtils.FORTIS_REGION) {
            handleNotify(Danger.DANGEROUS);
            return;
        }

        if (message.contains(TOA_DEATH_MSG)) {
            handleNotify(Danger.DANGEROUS);
        }
    }

    public void onScript(ScriptPreFired event) {
        if (event.getScriptId() == TOB_HUB_PORTAL_SCRIPT && event.getScriptEvent() != null) {
            Object[] args = event.getScriptEvent().getArguments();
            if (args != null && args.length > 1) {
                Object text = args[1];
                if (text instanceof String && ((String) text).contains(TOB_DEATH_MSG)) {
                    // https://oldschool.runescape.wiki/w/Theatre_of_Blood#Death_within_the_Theatre
                    handleNotify(Danger.DANGEROUS);
                }
            }
        }
    }

    public void onInteraction(InteractingChanged event) {
        if (event.getSource() == client.getLocalPlayer() && event.getTarget() != null && event.getTarget().getCombatLevel() > 0) {
            lastTarget = new WeakReference<>(event.getTarget());
        }
    }

    private void handleNotify(Danger dangerOverride) {
        int regionId = Objects.requireNonNull(WorldUtils.getLocation(client)).getRegionID();
        Danger danger = dangerOverride != null ? dangerOverride : WorldUtils.getDangerLevel(client, regionId, Set.of(ExceptionalDeath.values()));

        Collection<ItemData> items = ItemUtils.getInventoryItems(client, itemManager);
        // Slots are meaningless once stacks are split and merged into kept/lost lists
        items.forEach(item -> item.setInventorySlot(null));
        List<ItemData> itemsByPrice = getPricedItems(items);

        Pair<List<ItemData>, List<ItemData>> split;
        if (danger == Danger.DANGEROUS) {
            int keepCount = getKeepCount();
            split = splitItemsByKept(itemsByPrice, keepCount);
        } else {
            split = Pair.of(itemsByPrice, Collections.emptyList());
        }
        List<ItemData> keptItems = split.getLeft();
        List<ItemData> lostItems = split.getRight();

        long losePrice = ItemUtils.getStackGePrice(lostItems);

        Actor killer = identifyKiller();
        boolean npc = killer instanceof NPC;
        String killerName = killer != null ? StringUtils.defaultIfEmpty(killer.getName(), "?") : null;

        List<ItemData> lostStacks = getStacks(lostItems, true);
        List<ItemData> keptStacks = getStacks(keptItems, false);

        DeathEvent deathEvent = new DeathEvent(
                losePrice,
                danger,
                killerName,
                npc ? ((NPC) killer).getId() : null,
                keptStacks,
                lostStacks,
                client.getLocalPlayer().getWorldLocation()
        );

        messageBuilder.addEvent("death", deathEvent);
        tickUtils.sendNow();
    }

    /**
     * @return the number of items the player would keep on an unsafe death
     */
    private int getKeepCount() {
        if (Utils.getAccountType(client) == AccountType.ULTIMATE_IRONMAN)
            return 0;

        var skull = client.getLocalPlayer().getSkullIcon();
        int keepCount = skull == SkullIcon.NONE ? 3 : 0;
        if (client.getVarbitValue(VarbitID.PRAYER_PROTECTITEM) == 1)
            keepCount++;
        return keepCount;
    }

    /**
     * @return the inferred {@link Actor} who killed us, or null if not killed by an external source
     */
    @Nullable
    private Actor identifyKiller() {
        // must be in unsafe wildness or pvp world to be pk'd
        boolean pvpEnabled = !WorldUtils.isPvpSafeZone(client) &&
                (client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) > 0 || WorldUtils.isPvpWorld(client.getWorldType()));

        Player localPlayer = client.getLocalPlayer();
        Predicate<Actor> interacting = a -> INTERACTING.test(localPlayer, a);

        // O(1) fast path based on last outbound interaction
        Actor lastTarget = this.lastTarget.get();
        if (checkLastInteraction(localPlayer, lastTarget, pvpEnabled))
            return lastTarget;

        // find another player interacting with us (that is preferably not a friend or clan member)
        if (pvpEnabled) {
            Optional<? extends Player> pker = client.getTopLevelWorldView().players().stream()
                    .filter(interacting)
                    .min(PK_COMPARATOR.apply(localPlayer)); // O(n)
            if (pker.isPresent())
                return pker.get();
        }

        // otherwise search through NPCs interacting with us
        return client.getTopLevelWorldView().npcs().stream()
                .filter(interacting)
                .filter(npc -> NPC_VALID.test(npc.getTransformedComposition()))
                .min(NPC_COMPARATOR.apply(npcManager, localPlayer)) // O(n)
                .orElse(null);
    }

    /**
     * @param localPlayer {@link net.runelite.api.Client#getLocalPlayer()}
     * @param actor       the {@link Actor} that is a candidate killer from {@link #lastTarget}
     * @param pvpEnabled  whether a player could be our killer (e.g., in wilderness)
     * @return whether the specified actor is the likely killer of the local player
     */
    private static boolean checkLastInteraction(Player localPlayer, Actor actor, boolean pvpEnabled) {
        if (!INTERACTING.test(localPlayer, actor))
            return false;

        if (actor instanceof Player) {
            Player other = (Player) actor;
            return pvpEnabled
                    && !other.isClanMember()
                    && !other.isFriend()
                    && !other.isFriendsChatMember();
        }

        if (actor instanceof NPC) {
            NPC npcActor = (NPC) actor;
            NPCComposition npc = npcActor.getTransformedComposition();

            if (!NPC_VALID.test(npc)) return false;
            assert npc != null;

            return ArrayUtils.contains(npc.getActions(), ATTACK_OPTION);
        }

        log.warn("Encountered unknown type of Actor; was neither Player nor NPC!");
        return false;
    }

    /**
     * @param items       the items whose prices should be queried
     * @return pairs of the passed items to their price, sorted by most expensive unit price first
     */
    private static List<ItemData> getPricedItems(Collection<ItemData> items) {
        return items.stream()
                .sorted(Comparator.comparingLong(ItemData::getGePrice).reversed())
                .collect(Collectors.toList());
    }

    /**
     * Takes the complete list of items in the player's inventory and assigns them to separate lists,
     * depending on whether they would be kept or lost upon an unsafe death.
     *
     * @param itemsByPrice inventory items transformed by {@link #getPricedItems(Collection)}
     * @param keepCount    the number of items kept on death
     * @return the kept items on death (left) and lost items on death (right), in stable order, in separate lists
     */
    @VisibleForTesting
    static Pair<List<ItemData>, List<ItemData>> splitItemsByKept(List<ItemData> itemsByPrice, int keepCount) {
        List<ItemData> kept = new ArrayList<>();
        List<ItemData> lost = new ArrayList<>();

        int remainingKeeps = keepCount;

        for (ItemData item : itemsByPrice) {
            int id = item.getId();
            int quantity = item.getQuantity();

            // Bonds are always kept
            if (id == ItemID.OSRS_BOND
                    || id == ItemID.BOUGHT_OSRS_BOND
                    || id == ItemID.OSRS_BOND_UNTRADEABLE) {
                kept.add(item);
                continue;
            }

            boolean neverKept = ItemUtils.isItemNeverKeptOnDeath(id);

            if (neverKept || remainingKeeps <= 0) {
                lost.add(item);
                continue;
            }

            int toKeep = Math.min(quantity, remainingKeeps);
            int toLose = quantity - toKeep;

            if (toKeep > 0) {
                kept.add(new ItemData(item.getName(), id, item.getGePrice(), item.getHaPrice(), toKeep));
                remainingKeeps -= toKeep;
            }

            if (toLose > 0) {
                lost.add(new ItemData(item.getName(), id, item.getGePrice(), item.getHaPrice(), toLose));
            }
        }

        return Pair.of(kept, lost);
    }

    private static List<ItemData> getStacks(List<ItemData> items, boolean reduce) {
        if (!reduce) {
            // Preserve exact stacks
            return items.stream().map(ItemData::new).collect(Collectors.toList());
        }

        // Merge stacks with same ID
        Map<Integer, ItemData> merged = new LinkedHashMap<>();
        for (ItemData item : items) {
            merged.merge(item.getId(),
                    new ItemData(item), // copy
                    (existing, incoming) -> {
                        existing.setQuantity(existing.getQuantity() + incoming.getQuantity());
                        return existing;
                    });
        }

        return new ArrayList<>(merged.values());
    }

    static {
        INTERACTING = (localPlayer, a) -> a != null && a != localPlayer && !a.isDead() && a.getInteracting() == localPlayer;

        NPC_VALID = comp -> comp != null && comp.isInteractible() && !comp.isFollower() && comp.getCombatLevel() > 0;

        NPC_COMPARATOR = (npcManager, localPlayer) -> Comparator
                .comparing(
                        NPC::getTransformedComposition,
                        Comparator.nullsFirst(
                                Comparator
                                        .comparing(
                                                (NPCComposition comp) -> comp.getStringValue(ParamID.NPC_HP_NAME),
                                                Comparator.comparing(StringUtils::isNotEmpty) // prefer has name in hit points UI
                                        )
                                        .thenComparing(comp -> ArrayUtils.contains(comp.getActions(), ATTACK_OPTION)) // prefer explicitly attackable
                                        .thenComparingInt(NPCComposition::getCombatLevel) // prefer high level
                                        .thenComparingInt(NPCComposition::getSize) // prefer large
                                        .thenComparing(NPCComposition::isMinimapVisible) // prefer visible on minimap
                                        .thenComparing(
                                                // prefer high max health
                                                comp -> npcManager.getHealth(comp.getId()),
                                                Comparator.nullsFirst(Comparator.naturalOrder())
                                        )
                        )
                )
                .thenComparingInt(p -> -localPlayer.getLocalLocation().distanceTo(p.getLocalLocation())) // prefer nearby
                .reversed(); // for consistency with PK_COMPARATOR such that Stream#min should be used in #identifyKiller

        PK_COMPARATOR = localPlayer -> Comparator
                .comparing(Player::isClanMember) // prefer not in clan
                .thenComparing(Player::isFriend) // prefer not friend
                .thenComparing(Player::isFriendsChatMember) // prefer not fc
                .thenComparingInt(p -> Math.abs(localPlayer.getCombatLevel() - p.getCombatLevel())) // prefer similar level
                .thenComparingInt(p -> -p.getCombatLevel()) // prefer higher level for a given absolute level gap
                .thenComparing(p -> p.getOverheadIcon() == null) // prefer praying
                .thenComparing(p -> p.getTeam() == localPlayer.getTeam()) // prefer different team cape
                .thenComparingInt(p -> localPlayer.getLocalLocation().distanceTo(p.getLocalLocation())); // prefer nearby
    }
}

package haexporterplugin.notifiers;

import haexporterplugin.enums.CombatTaskTier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.util.Text;

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
public class CombatTaskNotifier extends BaseNotifier {

    private static final Pattern COMBAT_TASK_PATTERN = Pattern.compile(
            "Congratulations, you've completed an? (?<tier>easy|medium|hard|elite|master|grandmaster) combat task:(?<task>.+?)",
            Pattern.CASE_INSENSITIVE
    );

    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE) return;

        String msg = Text.removeTags(event.getMessage());
        Matcher matcher = COMBAT_TASK_PATTERN.matcher(msg);

        if (matcher.matches()) {
            String task = matcher.group("task");
            String tier = matcher.group("tier");

            CombatTaskTier parsedTier = CombatTaskTier.fromString(tier);
            if (parsedTier != null && parsedTier.compareTo(config.combatTaskMinTier()) < 0) {
                log.debug("Skipping combat task below minimum tier: {} (tier: {})", task, tier);
                return;
            }

            log.debug("Detected combat task completion: {} (tier: {})", task, tier);

            Map<String, Object> thisEvent = new HashMap<>();
            thisEvent.put("taskName", task);
            thisEvent.put("tier", tier);
            messageBuilder.addEvent("combatTask", thisEvent);
        }
    }

}

