package haexporterplugin.notifiers;

import haexporterplugin.data.ItemData;
import haexporterplugin.data.LootData;
import haexporterplugin.data.RareItemData;
import haexporterplugin.enums.LootCriteria;
import haexporterplugin.utils.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

import javax.inject.Inject;
import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.CopyOnWriteArraySet;
import java.util.function.Predicate;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

@Slf4j
public class LootNotifier extends BaseNotifier{

    private @Inject ItemManager itemManager;
    private @Inject KillCountTracker killCountTracker;

    public LootData lastDrop = null;


    public static final String GAUNTLET_BOSS = "Crystalline Hunllef", THE_GAUNTLET = "The Gauntlet";
    public static final String CG_NAME = "Corrupted Gauntlet", CG_BOSS = "Corrupted Hunllef";
    public static final String TOA = "Tombs of Amascut";
    public static final String TOB = "Theatre of Blood";
    public static final String COX = "Chambers of Xeric";

    public static final Set<String> SPECIAL_LOOT_NPC_NAMES = Set.of("The Whisperer", "Araxxor",
            "Branda the Fire Queen", "Eldric the Ice King", GAUNTLET_BOSS, CG_BOSS);

    public void init() {
        itemNameAllowlist.clear();
        itemNameAllowlist.addAll(
                Utils.readDelimited(config.lootItemAllowlist())
                        .map(Utils::regexify)
                        .filter(Objects::nonNull)
                        .collect(Collectors.toList())
        );

        itemNameDenylist.clear();
        itemNameDenylist.addAll(
                Utils.readDelimited(config.lootItemDenylist())
                        .map(Utils::regexify)
                        .filter(Objects::nonNull)
                        .collect(Collectors.toList())
        );

        sourceDenylist.clear();
        sourceDenylist.addAll(
                Utils.readDelimited(config.lootSourceDenylist())
                        .map(String::toLowerCase)
                        .collect(Collectors.toList())
        );
    }

    private boolean matchesAnyPattern(Collection<Pattern> patterns, String itemName) {
        return patterns.stream().anyMatch(pattern -> pattern.matcher(itemName).matches());
    }

    public void onServerNpcLoot(ServerNpcLoot serverNpcLoot) {
        var comp = serverNpcLoot.getComposition();
        var items = ItemUtils.itemsToItemDataList(serverNpcLoot.getItems(), itemManager);
        this.handleNotify(items, comp.getName(), LootRecordType.NPC, comp.getId());
    }

    public void onNpcLootReceived(NpcLootReceived npcLootReceived) {

        NPC npc = npcLootReceived.getNpc();
        int id = npc.getId();

        var items = ItemUtils.itemsToItemDataList(npcLootReceived.getItems(), itemManager);
        this.handleNotify(items, npc.getName(), LootRecordType.NPC, id);
    }

    public void onPlayerLootReceived(PlayerLootReceived playerLootReceived) {
        if (!config.lootIncludePlayer() || WorldUtils.isSafeArea(client))
            return;
        var items = ItemUtils.itemsToItemDataList(playerLootReceived.getItems(), itemManager);
        handleNotify(items, playerLootReceived.getPlayer().getName(), LootRecordType.PLAYER, null);
    }

    public void onGameMessage(String message) {
        if ("You have found a Pharaoh's sceptre! It fell on the floor.".equals(message)) {
            var items = ItemUtils.itemStackToItemData(new ItemStack(ItemID.PHARAOHS_SCEPTRE, 1), itemManager);
            this.handleNotify(List.of(items), "Pyramid Plunder", LootRecordType.EVENT, null);
        }
    }

    public void onLootReceived(LootReceived lootReceived) {

        var items = ItemUtils.itemsToItemDataList(lootReceived.getItems(), itemManager);
        // only consider non-NPC and non-PK loot
        if (lootReceived.getType() == LootRecordType.EVENT || lootReceived.getType() == LootRecordType.PICKPOCKET) {
            if (lootReceived.getType() == LootRecordType.PICKPOCKET && !config.lootIncludePickpocket()) {
                return;
            }
            if ("Barbarian Assault high gamble".equals(lootReceived.getName())) {
                // skip ba gambles
                return;
            }

            String source = getStandardizedSource(lootReceived);
            this.handleNotify(items, source, lootReceived.getType(), null);
        } else if (lootReceived.getType() == LootRecordType.NPC && SPECIAL_LOOT_NPC_NAMES.contains(lootReceived.getName())) {
            // Special case: upstream fires LootReceived for certain NPCs, but not NpcLootReceived
            String source = getStandardizedSource(lootReceived);
            var type = THE_GAUNTLET.equals(source) || CG_NAME.equals(source) ? LootRecordType.EVENT : lootReceived.getType();
            this.handleNotify(items, source, type, null);
        }
    }

    private final Collection<Pattern> itemNameAllowlist = new CopyOnWriteArrayList<>();
    private final Collection<Pattern> itemNameDenylist = new CopyOnWriteArrayList<>();
    private final Collection<String> sourceDenylist = new CopyOnWriteArraySet<>();

    private void handleNotify(Collection<ItemData> items, String dropper, LootRecordType type, Integer npcId) {
        // Recorded before any filtering: collection log items use the kill count of the drop they came from
        killCountTracker.onDrop(client.getTickCount());

        if (type != LootRecordType.PLAYER && sourceDenylist.contains(dropper.toLowerCase())) {
            log.debug("Skipping loot notif for denied loot source: {} ({})", dropper, type);
            return;
        }

        final int minValue = config.minLootValue();

        Collection<ItemData> reduced = ItemUtils.reduceItemStack(items);
        List<ItemData> serializedItems = new ArrayList<>(reduced.size());

        long totalStackValue = 0;
        boolean sendMessage = false;
        boolean onAllowList = false;
        ItemData max = null;
        RareItemData rarest = null;

        final double rarityThreshold = config.lootRarityThreshold() > 0 ? 1.0 / config.lootRarityThreshold() : Double.NaN;
        final boolean intersection = config.lootRarityValueIntersection() && Double.isFinite(rarityThreshold);
        for (ItemData item : reduced) {
            long totalPrice = ItemUtils.getStackGePrice(item);

            OptionalDouble rarity;
            if (type == LootRecordType.NPC) {
                rarity = rarityUtils.getRarity(dropper, item.getId(), item.getQuantity());
            } else if (type == LootRecordType.PICKPOCKET) {
                rarity = thievingUtils.getRarity(dropper, item.getId(), item.getQuantity());
            } else {
                rarity = OptionalDouble.empty();
            }

            boolean shouldSend;
            var criteria = EnumSet.noneOf(LootCriteria.class);
            if (totalPrice >= minValue) {
                criteria.add(LootCriteria.VALUE);
            }
            if (MathUtils.lessThanOrEqual(rarity.orElse(1), rarityThreshold)) {
                criteria.add(LootCriteria.RARITY);
            }
            if (intersection) {
                shouldSend = criteria.contains(LootCriteria.VALUE) && (rarity.isEmpty() || criteria.contains(LootCriteria.RARITY));
            } else {
                shouldSend = criteria.contains(LootCriteria.VALUE) || criteria.contains(LootCriteria.RARITY);
            }

            boolean denied = matchesAnyPattern(itemNameDenylist, item.getName());
            if (denied) {
                shouldSend = false;
                criteria.add(LootCriteria.DENYLIST);
            } else {
                if (matchesAnyPattern(itemNameAllowlist, item.getName())) {
                    shouldSend = true;
                    onAllowList = true;
                    criteria.add(LootCriteria.ALLOWLIST);
                }
                if (max == null || totalPrice > ItemUtils.getStackGePrice(max)) {
                    max = item;
                }
            }

            if (shouldSend) {
                sendMessage = true;
            }

            if (rarity.isPresent()) {
                RareItemData rareItem = RareItemData.of(item, rarity.getAsDouble());
                serializedItems.add(rareItem);
                if (!denied && (rarest == null || rareItem.getRarity() < rarest.getRarity())) {
                    rarest = rareItem;
                }
            } else {
                serializedItems.add(item);
            }
            totalStackValue += totalPrice;
        }

        Evaluable sourceLink = type == LootRecordType.PLAYER
                ? ReplacementUtils.ofLink(dropper, config.playerLookupService().getPlayerUrl(dropper))
                : ReplacementUtils.ofWiki(dropper);

        if (sendMessage || onAllowList) {
            // Send regular loot notification (or allowlisted item)
            LootData lootData = new LootData(
                    serializedItems,
                    max,
                    totalStackValue,
                    sourceLink,
                    type,
                    npcId,
                    Collections.emptySet()
            );
            messageBuilder.addEvent("loot", lootData);
            tickUtils.sendNow();
        } else if (config.lootIncludePkChest() && totalStackValue >= minValue && max != null && "Loot Chest".equalsIgnoreCase(dropper)) {
            // Special case: PK loot keys should trigger notification if total value exceeds configured minimum even
            // if no single item itself would exceed the min value config
            LootData lootData = new LootData(
                    serializedItems,
                    max,
                    totalStackValue,
                    sourceLink,
                    type,
                    npcId,
                    Collections.emptySet()
            );
            messageBuilder.addEvent("pkLoot", lootData);
            tickUtils.sendNow();
        }
    }

    public String getStandardizedSource(LootReceived event) {
        if (GAUNTLET_BOSS.equals(event.getName())) {
            return THE_GAUNTLET;
        } else if (CG_BOSS.equals(event.getName())) {
            return CG_NAME;
        } else if (lastDrop != null && shouldUseChatName(event)) {
            return lastDrop.getSource().toString(); // distinguish entry/expert/challenge modes
        }
        return event.getName();
    }

    private boolean shouldUseChatName(LootReceived event) {
        assert lastDrop != null;
        if (event.getType() != LootRecordType.EVENT) return false;
        String lastSource = lastDrop.getSource().toString();
        Predicate<String> coincides = source -> source.equals(event.getName()) && lastSource.startsWith(source);
        return coincides.test(TOA) || coincides.test(TOB) || coincides.test(COX);
    }

    public void onConfigChanged(String key, String value) {
        if ("lootSourceDenylist".equals(key)) {
            sourceDenylist.clear();
            sourceDenylist.addAll(
                    Utils.readDelimited(value)
                    .map(String::toLowerCase)
                    .collect(Collectors.toList())
            );
            return;
        }

        Collection<Pattern> itemNames;
        if ("lootItemAllowlist".equals(key)) {
            itemNames = itemNameAllowlist;
        } else if ("lootItemDenylist".equals(key)) {
            itemNames = itemNameDenylist;
        } else {
            return;
        }

        itemNames.clear();
        itemNames.addAll(
                Utils.readDelimited(value)
                .map(Utils::regexify)
                .filter(Objects::nonNull)
                .collect(Collectors.toList())
        );
    }
}

package haexporterplugin;

import com.google.inject.Provides;
import javax.inject.Inject;

import haexporterplugin.data.HealthData;
import haexporterplugin.data.PrayerData;
import haexporterplugin.data.SpellbookData;
import haexporterplugin.notifiers.*;
import haexporterplugin.utils.EasterEggUtils;
import haexporterplugin.utils.HomeAssistUtils;
import haexporterplugin.utils.MessageBuilder;
import haexporterplugin.utils.TickUtils;
import haexporterplugin.utils.Utils;
import haexporterplugin.utils.WorldUtils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.*;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "HA Exporter",
	description = "Export Game data to your HomeAssistant"
)
public class HAExporterPlugin extends Plugin
{
	// Sent to endpoints as X-Osrs-Exporter-Version. Must match `version` in build.gradle (checked by PluginVersionTest).
	public static final String PLUGIN_VERSION = "1.5.1";

	@Inject
	private Client client;

	@Inject
	private HAExporterConfig config;

	@Inject
	private MessageBuilder messageBuilder;

	@Inject
	private ClientToolbar clientToolbar;

    private NavigationButton navButton;
	private @Inject TickUtils tickUtils;
	private @Inject AchievementDiaryNotifier achievementDiaryNotifier;
	private @Inject CombatTaskNotifier combatTaskNotifier;
	private @Inject SuperiorNotifier superiorNotifier;
	private @Inject LevelNotifier levelNotifier;
	private @Inject ItemNotifier itemNotifier;
	private @Inject LootNotifier lootNotifier;
	private @Inject LocationNotifier locationNotifier;
	private @Inject DeathNotifier deathNotifier;
	private @Inject CollectionNotifier collectionNotifier;
	private @Inject EasterEggUtils easterEggUtils;
	private @Inject HomeAssistUtils homeAssistUtils;
	private boolean initialized = false;

	@Override
	protected void startUp() throws Exception
	{
        HAExporterPanel panel = injector.getInstance(HAExporterPanel.class);
		navButton = NavigationButton.builder()
			.tooltip("HA Exporter")
			.icon(ImageUtil.loadImageResource(getClass(), "/ha-exporter-icon.png"))
			.priority(420)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		homeAssistUtils.startUp();
		panel.initialize();
		lootNotifier.init();

		easterEggUtils.init();

		log.debug("HA Exporter Started");
	}

	@Override
	protected void shutDown() throws Exception
	{
		messageBuilder.addEvent("clientShutdown", "Disabled");
		tickUtils.sendNow();
		// Stop resending queued payloads; the "Disabled" message above is still attempted once
		homeAssistUtils.shutDown();
		easterEggUtils.shutDown();
		clientToolbar.removeNavigation(navButton);
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		if (!initialized) return;
		messageBuilder.addEvent("clientShutdown", "Shutdown");
		tickUtils.sendShutdown();
	}

	@Subscribe
	public void onAccountHashChanged(AccountHashChanged event)
	{
		// initialize() reads the hash itself, so only update once the player has been initialized
		if (!initialized) return;
		messageBuilder.setData("accounthash", Utils.accountHash(client.getAccountHash()));
	}

	@Subscribe
	public void onPlayerLootReceived(PlayerLootReceived playerLootReceived) {
		lootNotifier.onPlayerLootReceived(playerLootReceived);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		messageBuilder.setState(gameStateChanged.getGameState());
		levelNotifier.onGameStateChanged(gameStateChanged);
		collectionNotifier.onGameStateChanged(gameStateChanged);
		if (gameStateChanged.getGameState() == GameState.HOPPING)
		{
			initialized = false;
		}
		if (gameStateChanged.getGameState() == GameState.LOGIN_SCREEN)
		{
			messageBuilder.addEvent("clientShutdown", "Logout");
			tickUtils.sendNow();
			initialized = false;
			messageBuilder.resetData();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged statChanged)
	{
		var exp = statChanged.getSkill();

		if (statChanged.getSkill() == Skill.HITPOINTS){
			HealthData health = new HealthData(statChanged.getBoostedLevel(), client.getRealSkillLevel(Skill.HITPOINTS));
			messageBuilder.setData("health", health);
			if (config.sendHealthInstantly()) {
				tickUtils.sendNow();
			}
		}
		if (statChanged.getSkill() == Skill.PRAYER){
			PrayerData prayer = new PrayerData(statChanged.getBoostedLevel(), client.getRealSkillLevel(Skill.PRAYER));
			messageBuilder.setData("prayer", prayer);
			if (config.sendPrayerInstantly()) {
				tickUtils.sendNow();
			}
		}
	}

	@Subscribe(priority = 1) // run before the base loot tracker plugin
	public void onChatMessage(ChatMessage chatMessage) {
		String source = chatMessage.getName() != null && !chatMessage.getName().isEmpty() ? chatMessage.getName() : chatMessage.getSender();
		switch (chatMessage.getType()){
			case GAMEMESSAGE:
				if ("runelite".equals(source)) {
					// filter out plugin-sourced chat messages
					return;
				}
				lootNotifier.onGameMessage(chatMessage.getMessage());
				deathNotifier.onGameMessage(chatMessage.getMessage());
				combatTaskNotifier.onChatMessage(chatMessage);
				achievementDiaryNotifier.onChatMessage(chatMessage);
				superiorNotifier.onChatMessage(chatMessage);
				collectionNotifier.onChatMessage(chatMessage);
				break;
		}

	}

	@Subscribe(priority = 1) // run before the base loot tracker plugin
	public void onServerNpcLoot(ServerNpcLoot serverNpcLoot) {
		// temporarily only use new event when needed
		int npcId = serverNpcLoot.getComposition().getId();
		var name = serverNpcLoot.getComposition().getName();
		if (npcId != NpcID.YAMA && npcId != NpcID.HESPORI && !name.startsWith("Hallowed Sepulchre")) {
			return;
		}

		lootNotifier.onServerNpcLoot(serverNpcLoot);
	}

	@Subscribe(priority = 1) // run before the base loot tracker plugin
	public void onNpcLootReceived(NpcLootReceived npcLootReceived) {
		if (npcLootReceived.getNpc().getId() == NpcID.YAMA) {
			// handled by ServerNpcLoot, but return just in case
			return;
		}

		lootNotifier.onNpcLootReceived(npcLootReceived);
	}

	@Subscribe
	public void onLootReceived(LootReceived lootReceived) {
		lootNotifier.onLootReceived(lootReceived);
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event) {
		deathNotifier.onScript(event);
		collectionNotifier.onScript(event);
	}

	@Subscribe
	public void onActorDeath(ActorDeath actor) {
		deathNotifier.onActorDeath(actor);
		if (client.getLocalPlayer() == actor.getActor()){
			easterEggUtils.playGarbage();
		}
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event) {
		deathNotifier.onInteraction(event);
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned npcSpawned) {
		superiorNotifier.onNpcSpawned(npcSpawned);
	}

	@Subscribe
	public void onGameTick(GameTick gameTick){
		tickUtils.onTick();

		updateSpellbook();

		levelNotifier.onTick();
		itemNotifier.onTick();
		locationNotifier.onTick();
		superiorNotifier.onGameTick();

		if (!initialized){
			initialize();
		}

		tickUtils.sendOnSendRate();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		messageBuilder.setTickDelay(config.sendRate());
		lootNotifier.onConfigChanged(event.getKey(), event.getNewValue());
	}

	@Provides
	HAExporterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HAExporterConfig.class);
	}

	private void initialize(){
		if (client.getLocalPlayer() != null){
			String name = client.getLocalPlayer().getName();

			messageBuilder.setData("world", String.valueOf(client.getWorld()));
			messageBuilder.setData("worldtypes", WorldUtils.getWorldTypeNames(client.getWorldType()));
			int accountType = client.getVarbitValue(VarbitID.IRONMAN);
			messageBuilder.setData("accounttype", String.valueOf(accountType));
            assert name != null;
            messageBuilder.setData("name", name);
			messageBuilder.setData("accounthash", Utils.accountHash(client.getAccountHash()));

			// Get and set Health & Prayer
			HealthData health = new HealthData(client.getBoostedSkillLevel(Skill.HITPOINTS), client.getRealSkillLevel(Skill.HITPOINTS));
			PrayerData prayer = new PrayerData(client.getBoostedSkillLevel(Skill.PRAYER), client.getRealSkillLevel(Skill.PRAYER));
			messageBuilder.setData("health", health);
			messageBuilder.setData("prayer", prayer);
			messageBuilder.setTickDelay(config.sendRate());

			tickUtils.sendNow();

			initialized = true;
		}
	}

	private void updateSpellbook(){
		int spellbookId = client.getVarbitValue(VarbitID.SPELLBOOK);
		SpellbookData spellbook = new SpellbookData(spellbookId);
		messageBuilder.setData("spellbook", spellbook);
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		if (event.getMenuOption().equals("Eat") && (event.getItemId() == ItemID.KEBAB || event.getItemId() == ItemID.UGTHANKI_KEBAB || event.getItemId() == ItemID.SUPER_KEBAB || event.getItemId() == ItemID.VARLAMORIAN_KEBAB)) {
			easterEggUtils.playKebab();
		}
	}
}

